head.b:skin:
    /* ============================================================
       dot.tag — clean, minimal, Instagram-inspired redesign
       Light default + optional Dark. Flat. Subtle blue accent.
       ============================================================ */
    :root{
      --bg:#ffffff;
      --panel:#ffffff;
      --panel2:#fafafa;
      --blue:#1a73e8;
      --blue-weak:#e8f0fe;
      --text:#111111;
      --muted:#737373;
      --line:#dbdbdb;
      --line-soft:#efefef;
      --danger:#ed4956;
      --radius:8px;
      --radius-lg:12px;
      --msg-bg:#ffffff;
      --bubble-mine:#3797f0;
      --bubble-other:#f0f0f0;
      --nav-h:54px;
    }
    [data-theme="dark"]{
      --bg:#000000;
      --panel:#000000;
      --panel2:#121212;
      --blue:#4a9eff;
      --blue-weak:#16283d;
      --text:#f5f5f5;
      --muted:#a8a8a8;
      --line:#262626;
      --line-soft:#1a1a1a;
      --msg-bg:#000000;
      --bubble-mine:#3797f0;
      --bubble-other:#262626;
    }
    *{box-sizing:border-box}
    html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);
      font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
      transition:background .2s,color .2s;-webkit-font-smoothing:antialiased;}
    body{padding-bottom:calc(var(--nav-h) + 16px + env(safe-area-inset-bottom))}
    a{color:inherit;text-decoration:none}
    button,input,textarea{font:inherit;color:inherit}
    button{cursor:pointer;transition:opacity .15s ease,background .15s ease}
    button:active{opacity:.7}
    button:disabled{opacity:.5;cursor:not-allowed}
    .blogger-shell{display:none}
    .hidden{display:none!important}
    .small{font-size:12px}
    .muted{color:var(--muted)}
    .full{width:100%}
    .grow{flex:1;min-width:0}
    .truncate{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

    /* ---------- Boot ---------- */
    .boot-screen{min-height:100vh;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;padding:24px;text-align:center;color:var(--muted)}
    .boot-spinner{width:28px;height:28px;border:2px solid var(--line);border-top-color:var(--blue);border-radius:50%;animation:dotspin .8s linear infinite}
    @keyframes dotspin{to{transform:rotate(360deg)}}

    /* ---------- Layout ---------- */
    .app{max-width:600px;margin:0 auto;min-height:100vh;background:var(--bg);position:relative}
    .content{padding:16px 16px 24px}
    .topbar{height:54px;display:flex;align-items:center;gap:10px;padding:0 16px;border-bottom:1px solid var(--line);
      position:sticky;top:0;background:var(--bg);z-index:20}
    .brandmark{width:32px;height:32px;border-radius:8px;background:var(--blue);display:grid;place-items:center;color:#fff;flex-shrink:0}
    .dot-logo-svg{width:72%;height:72%;display:block}
    .brand{font-size:20px;font-weight:700;letter-spacing:-.4px;color:var(--text)}
    .brand span{color:var(--blue)}
    .top-spacer{flex:1}
    .icon-btn{border:1px solid transparent;background:var(--bg);color:var(--text);width:40px;height:40px;border-radius:50%;
      display:grid;place-items:center;font-size:19px;position:relative}
    .icon-btn:active{background:var(--panel2)}

    /* ---------- Cards / generic ---------- */
    .card{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius-lg);padding:16px;margin-bottom:12px}
    .primary{background:var(--blue);color:#fff;border:0;border-radius:var(--radius);padding:12px 16px;font-weight:600;min-height:44px;font-size:14px}
    .secondary{background:var(--panel2);border:1px solid var(--line);color:var(--text);border-radius:var(--radius);padding:10px 14px;min-height:40px;font-size:14px;font-weight:500}
    .field,.search{width:100%;background:var(--panel2);color:var(--text);border:1px solid var(--line);border-radius:var(--radius);
      padding:12px;margin:6px 0 12px;outline:none;font-size:14px;transition:border-color .15s}
    .field:focus,.search:focus{border-color:var(--blue)}
    .field::placeholder,.search::placeholder{color:var(--muted)}
    label{font-size:12px;color:var(--muted);display:block;margin-bottom:2px;font-weight:500}
    .eyebrow{font-size:11px;letter-spacing:1.4px;color:var(--blue);font-weight:700;text-transform:uppercase}
    h1,h2,h3,p{margin-top:0}
    h1{font-size:24px;letter-spacing:-.4px;margin:6px 0;color:var(--text);font-weight:700}
    h2{font-size:17px;margin-bottom:10px;color:var(--text);font-weight:700}
    .status{font-size:12px;margin:8px 0;color:var(--danger);min-height:16px;overflow-wrap:anywhere}
    .notice{font-size:12px;line-height:1.5;color:var(--muted);margin-top:12px}
    .section-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:4px 0 14px}
    .section-head h1{margin:0}
    .pill{font-size:10px;background:var(--blue-weak);color:var(--blue);border:0;padding:4px 8px;border-radius:6px;font-weight:600}
    .empty{text-align:center;padding:40px 16px;color:var(--muted)}
    .empty .big{font-size:36px;margin-bottom:12px}
    .footer-note{text-align:center;color:var(--muted);font-size:11px;padding:16px}

    /* ---------- Auth ---------- */
    .auth-wrap{max-width:400px;margin:5vh auto;padding:24px 20px}
    .auth-logo{text-align:center;margin-bottom:24px}
    .auth-logo .brandmark{width:60px;height:60px;border-radius:16px;margin:0 auto 12px}
    .auth-logo h1{font-size:30px;letter-spacing:-.6px}
    .auth-logo p{color:var(--muted);font-size:14px}
    .auth-switch{text-align:center;margin-top:16px;font-size:13px;color:var(--muted)}
    .link-button{background:none;border:0;color:var(--blue);font-weight:600;padding:6px}
    .auth-forgot-row{display:flex;justify-content:flex-end;margin:-2px 0 12px}
    .auth-forgot-link{font-size:13px;padding:6px 2px;min-height:30px;cursor:pointer}

    /* ---------- Welcome / home header ---------- */
    .welcome-card{margin:0 0 20px;padding:0;border:0;background:transparent}
    .welcome-card .section-head{margin:0;align-items:center}
    .welcome-card h1{font-size:22px;line-height:1.2}

    /* ---------- Avatars ---------- */
    .avatar{width:44px;height:44px;border-radius:50%;background:var(--panel2);color:var(--text);
      display:grid;place-items:center;flex-shrink:0;font-size:16px;font-weight:600;overflow:hidden;position:relative;border:1px solid var(--line)}
    .avatar img{width:100%;height:100%;object-fit:cover}
    .avatar.online::after{content:'';position:absolute;bottom:0;right:0;width:11px;height:11px;background:#4caf50;border:2px solid var(--panel);border-radius:50%}

    /* ---------- Chat list (WhatsApp-style) ---------- */
    .chat-row{display:flex;align-items:center;gap:12px;padding:10px 4px;border-bottom:1px solid var(--line-soft);cursor:pointer}
    .chat-row:last-child{border-bottom:0}
    .chat-row:active{background:var(--panel2);border-radius:10px}
    .chat-name{font-size:15px;font-weight:600;margin-bottom:2px;color:var(--text)}
    .chat-preview{font-size:13px;color:var(--muted)}

    /* ---------- Chat room ---------- */
    #chatsView{position:relative}
    #chatRoomView{display:flex;flex-direction:column;height:100dvh;position:fixed;top:0;left:0;right:0;bottom:0;z-index:999;background:var(--msg-bg)}
    .chat-header{display:flex;align-items:center;gap:10px;padding:8px 12px;border-bottom:1px solid var(--line);background:var(--bg);position:relative;flex:0 0 auto;z-index:2;min-height:56px}
    .back-btn{border:0;background:none;color:var(--text);font-size:26px;padding:2px 8px;line-height:1}
    .messages{display:flex;flex-direction:column-reverse;gap:6px;padding:12px;overflow-y:auto;flex:1 1 auto;min-height:0;
      background:var(--msg-bg);overscroll-behavior:contain;-webkit-overflow-scrolling:touch}
    .typing-indicator{padding:4px 14px;font-size:12px;color:var(--muted);font-style:italic;min-height:18px}
    .typing-indicator .dot{display:inline-block;width:5px;height:5px;background:var(--muted);border-radius:50%;margin:0 1px;animation:typingDot 1.4s infinite}
    .typing-indicator .dot:nth-child(2){animation-delay:.2s}
    .typing-indicator .dot:nth-child(3){animation-delay:.4s}
    @keyframes typingDot{0%,60%,100%{opacity:.3;transform:translateY(0)}30%{opacity:1;transform:translateY(-3px)}}
    .bubble{max-width:80%;padding:8px 12px;border-radius:16px;background:var(--bubble-other);color:var(--text);
      align-self:flex-start;overflow-wrap:anywhere;line-height:1.4;font-size:14px;display:flex;flex-direction:column;gap:3px}
    .bubble.mine{align-self:flex-end;color:#fff;background:var(--bubble-mine);border-bottom-right-radius:4px}
    .bubble:not(.mine){border-bottom-left-radius:4px}
    .bubble-text{overflow-wrap:anywhere;white-space:pre-wrap;line-height:1.4}
    .bubble-image{max-width:100%;max-height:300px;border-radius:10px;display:block;margin-bottom:2px;cursor:pointer}
    .bubble-time{font-size:10px;opacity:.75;text-align:right;font-weight:500;align-self:flex-end;display:flex;align-items:center;gap:3px}
    .bubble.mine .bubble-time{color:rgba(255,255,255,.9)}
    .bubble:not(.mine) .bubble-time{color:var(--muted)}
    .read-tick{font-size:11px;font-weight:600}
    .read-tick.sent{opacity:.7}
    .read-tick.read{color:#9ad2ff}
    .composer{position:relative;flex:0 0 auto;z-index:10;display:flex;gap:8px;padding:8px 10px;background:var(--bg);
      border-top:1px solid var(--line);padding-bottom:max(8px,env(safe-area-inset-bottom))}
    .composer input{flex:1;min-width:0;background:var(--panel2);color:var(--text);border:1px solid var(--line);border-radius:20px;padding:10px 14px;outline:none;font-size:14px}
    .attach-btn{width:40px;border:0;border-radius:20px;background:transparent;color:var(--muted);font-size:18px;flex-shrink:0}
    .send-btn{width:44px;border:0;border-radius:20px;background:var(--blue);color:#fff;font-size:18px;flex-shrink:0}

    /* ---------- FAB ---------- */
    .fab{position:fixed;right:max(16px,calc((100vw - 600px)/2 + 12px));bottom:calc(var(--nav-h) + 20px + env(safe-area-inset-bottom));
      width:48px;height:48px;padding:0;display:grid;place-items:center;border:0;border-radius:50%;background:var(--blue);color:#fff;
      font-size:24px;line-height:1;box-shadow:0 2px 8px rgba(0,0,0,.15);z-index:30}

    /* ---------- Bottom nav ---------- */
    .bottom-nav{position:fixed;left:0;right:0;bottom:0;height:calc(var(--nav-h) + env(safe-area-inset-bottom));
      padding-bottom:env(safe-area-inset-bottom);display:flex;justify-content:space-around;align-items:center;
      background:var(--bg);border-top:1px solid var(--line);z-index:100;max-width:600px;margin:0 auto}
    .bottom-nav.hidden{display:none!important}
    .nav-btn{position:relative;flex:1;height:var(--nav-h);padding:0;display:flex;flex-direction:column;align-items:center;
      justify-content:center;gap:2px;border:0;border-radius:0;background:transparent;color:var(--muted);font-size:10px;font-weight:500}
    .nav-btn b{display:flex;align-items:center;justify-content:center;width:24px;height:24px;font-size:22px;font-weight:400}
    .profile-nav-icon{display:block;width:22px;height:22px}
    .nav-btn.active{color:var(--text);font-weight:600}
    .nav-btn#createBtn{color:var(--muted)}
    .nav-btn#createBtn b{width:36px;height:36px;border-radius:50%;background:var(--blue);color:#fff;font-size:24px;font-weight:400}

    /* ---------- Feed post ---------- */
    .feed-post{background:var(--panel);border-bottom:1px solid var(--line);margin:0 0 8px;overflow:hidden}
    .post-meta{display:flex;align-items:center;gap:10px;padding:10px 12px}
    .post-meta .avatar{width:36px;height:36px;font-size:14px;border:1px solid var(--line)}
    .post-meta strong{font-size:13px;font-weight:600;display:block}
    .post-meta .muted.small{font-size:11px}
    .post-time{font-size:11px;color:var(--muted);margin-top:2px}
    .post-image{display:block;width:100%;max-height:520px;object-fit:cover;background:var(--panel2)}
    .post-text{padding:12px;font-size:14px;line-height:1.5;white-space:pre-wrap;overflow-wrap:anywhere;color:var(--text)}
    .post-composer-preview{width:100%;max-height:280px;object-fit:contain;border-radius:8px;background:var(--panel2);margin:8px 0}
    .post-actions{display:flex;gap:16px;padding:8px 12px 12px;color:var(--muted)}
    .post-actions button{border:0;background:none;color:var(--text);padding:4px 0;font-weight:600;font-size:13px}
    .like-btn{display:inline-flex;align-items:center;gap:6px;padding:4px 0!important;border-radius:0}
    .like-btn.liked{color:var(--danger)!important}
    .like-btn .heart{font-size:18px;line-height:1}
    .like-btn .like-count{font-size:13px;color:var(--muted);font-weight:500}
    .like-btn.liked .like-count{color:var(--text)}
    .post-owner-actions{margin-left:auto;display:flex;align-items:center;gap:6px}
    .post-more-btn{width:32px;height:32px;border-radius:50%;border:0!important;background:transparent!important;color:var(--muted)!important;font-size:20px!important;padding:0!important}

    /* ---------- Profile ---------- */
    .profile-container{max-width:600px;margin:0 auto}
    .profile-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}
    .profile-header h1{font-size:22px;font-weight:700}
    .modern-profile-card{display:flex;flex-direction:column;padding:0 0 8px}
    .profile-3d-shell{margin:0 0 8px;padding:0;border:0;border-radius:0;background:transparent;box-shadow:none;transform:none!important}
    .profile-menu-wrap{position:relative;flex-shrink:0}
    .profile-menu-trigger{width:40px;height:40px;display:grid;place-items:center;border-radius:50%;border:1px solid var(--line);
      background:var(--bg);color:var(--text);font-size:22px;font-weight:600;line-height:1;cursor:pointer}
    .profile-menu-panel{position:absolute;right:0;top:48px;z-index:1000;width:min(230px,calc(100vw - 48px));padding:6px;
      border:1px solid var(--line);border-radius:10px;background:var(--panel);box-shadow:0 4px 20px rgba(0,0,0,.12)}
    .profile-menu-panel[hidden]{display:none!important}
    .profile-menu-email{padding:10px 11px 12px;border-bottom:1px solid var(--line);margin-bottom:4px;overflow-wrap:anywhere;font-size:12px;color:var(--muted)}
    .profile-menu-panel button{width:100%;min-height:40px;text-align:left;padding:10px 12px;border:0;border-radius:6px;background:transparent;color:var(--text);font-size:14px;font-weight:500}
    .profile-menu-panel button:active{background:var(--panel2)}
    .profile-menu-panel #deleteAccountBtn{color:var(--danger)}

    /* Modern profile hero — Instagram-inspired */
    .modern-profile-card{display:flex;flex-direction:column;align-items:stretch;padding:8px 4px 8px}
    .avatar-wrapper{position:relative;margin:0 auto 16px;align-self:center}
    .modern-avatar{width:88px;height:88px;border-radius:50%;padding:0;background:var(--line-soft)}
    .modern-avatar-inner{width:100%;height:100%;border-radius:50%;background:var(--panel2);overflow:hidden;position:relative}
    .modern-avatar-inner img{width:100%;height:100%;object-fit:cover}
    .modern-avatar-inner span{display:flex;width:100%;height:100%;align-items:center;justify-content:center;font-size:32px;font-weight:600;color:var(--text);background:var(--panel2)}
    .edit-icon-btn{position:absolute;bottom:0;right:0;width:28px;height:28px;border-radius:50%;background:var(--blue);color:#fff;
      border:2px solid var(--bg);display:grid;place-items:center;font-size:12px;cursor:pointer;padding:0}
    .modern-name{font-size:17px;font-weight:700;margin:0 0 2px;text-align:center}
    .modern-handle{font-size:13px;color:var(--muted);font-weight:500;margin:0 0 8px;text-align:center}
    .modern-bio{font-size:13px;color:var(--text);text-align:center;max-width:90%;margin:0 auto 16px;line-height:1.4;font-weight:400}
    .modern-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));align-items:stretch;gap:0;width:100%;max-width:100%;
      margin:0 auto 16px;padding:10px 0;border-top:1px solid var(--line-soft);border-bottom:1px solid var(--line-soft)}
    .modern-stat{text-align:center;cursor:pointer;min-width:0;padding:6px 2px;border-radius:0;display:flex;flex-direction:column;align-items:center;justify-content:center}
    .modern-stat strong{display:block;font-size:17px;line-height:1.2;font-weight:700;color:var(--text);font-variant-numeric:tabular-nums}
    .modern-stat span{display:block;margin-top:2px;font-size:11px;line-height:1.2;color:var(--muted);font-weight:500}
    #openFollowers:active,#openFollowing:active{background:var(--panel2);border-radius:8px}

    /* Profile grid (3-col like Instagram) */
    .profile-posts-tabs{display:flex;margin:0 0 4px;border-bottom:1px solid var(--line)}
    .profile-posts-tabs>div{flex:1;text-align:center;padding:10px;font-weight:700;font-size:12px;color:var(--text);border-bottom:2px solid var(--text);letter-spacing:.5px}
    #profilePostsGrid,#publicPostsGrid{display:grid;grid-template-columns:repeat(3,1fr);gap:2px;padding-bottom:20px}

    /* Public profile */
    .profile-hero{text-align:center;padding:16px;border:0;border-radius:0;background:transparent;margin-bottom:0}
    .profile-hero .avatar{width:80px;height:80px;margin:0 auto 12px;font-size:26px}
    .profile-photo-actions{display:flex;gap:8px;justify-content:center;flex-wrap:wrap;margin:10px 0 16px}
    .profile-photo-actions input{display:none}
    .public-profile-actions{display:flex;gap:8px;justify-content:center;flex-wrap:wrap;margin:12px 0}
    .public-profile-actions button{flex:1;min-width:0;max-width:160px}
    .follow-list-row{display:flex;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid var(--line-soft);min-width:0}
    .follow-list-row:last-child{border-bottom:0}
    .follow-list-row .grow{cursor:pointer}
    .follow-list-row .avatar{width:42px;height:42px}
    .follow-list-actions{display:flex;align-items:center;gap:5px;flex-shrink:0}
    .follow-list-actions button{font-size:12px;min-height:32px;padding:6px 10px;border-radius:6px}
    .follow-btn{min-width:0;padding:8px 16px;border-radius:6px;font-weight:600}
    .follow-btn.following{background:var(--panel2);border:1px solid var(--line);color:var(--text)}

    /* ---------- People / explore ---------- */
    .people-result{width:100%;min-width:0}
    .people-result-main{display:flex;align-items:center;gap:12px;min-width:0}
    .people-result-main .grow{overflow:hidden}
    .people-result-name,.people-result-handle,.people-result-bio{display:block;overflow-wrap:anywhere}
    .people-result-bio{margin-top:4px}
    .people-result-actions{display:flex;gap:6px;margin:10px 0 0 0;width:100%}
    .people-result-actions button{flex:1 1 0;min-width:0;padding:8px 3px;font-size:12px;line-height:1.2;white-space:nowrap;min-height:36px}

    /* ---------- Notifications ---------- */
    .notify-badge{position:absolute;right:2px;top:2px;min-width:16px;height:16px;padding:0 4px;border-radius:99px;background:var(--danger);color:#fff;
      font-size:9px;font-weight:700;display:grid;place-items:center;border:2px solid var(--bg)}
    .notification-actions{display:flex;gap:8px;flex-wrap:wrap;margin:8px 0 12px;align-items:center}
    .notification-row{display:flex;align-items:flex-start;gap:10px;padding:12px 4px;border-bottom:1px solid var(--line-soft);cursor:pointer}
    .notification-row:last-child{border-bottom:0}
    .notification-row.unread{background:var(--blue-weak);border-radius:8px;padding-left:8px;padding-right:8px}
    .notification-row .avatar{width:40px;height:40px;font-size:14px}
    .notification-copy{flex:1;min-width:0;font-size:13px;line-height:1.4}
    .notification-time{font-size:11px;color:var(--muted);margin-top:3px}
    .notification-dot{width:6px;height:6px;border-radius:50%;background:var(--blue);flex-shrink:0;margin-top:6px}

    /* ---------- Context menu / dialogs ---------- */
    .notification-row,.chat-row,.bubble{-webkit-touch-callout:none;user-select:none;-webkit-user-select:none;touch-action:pan-y}
    .dot-context-menu{position:fixed;z-index:999999;min-width:170px;padding:6px;background:var(--panel);color:var(--text);
      border:1px solid var(--line);border-radius:10px;box-shadow:0 4px 24px rgba(0,0,0,.16);display:flex;flex-direction:column;gap:2px;animation:dotMenuIn .12s ease-out}
    @keyframes dotMenuIn{from{opacity:0;transform:scale(.97)}to{opacity:1;transform:scale(1)}}
    .dot-context-menu button{appearance:none;border:0;border-radius:6px;background:transparent;color:var(--text);text-align:left;padding:10px 12px;min-height:40px;font-size:14px;font-weight:500}
    .dot-context-menu button:active{background:var(--panel2)}
    .dot-context-menu button.danger{color:var(--danger)}
    .dot-dialog-backdrop{position:fixed;inset:0;z-index:1000000;display:flex;align-items:center;justify-content:center;padding:18px;background:rgba(0,0,0,.45);animation:dotDialogFade .16s ease}
    @keyframes dotDialogFade{from{opacity:0}to{opacity:1}}
    .dot-dialog{position:relative;flex:0 1 340px;width:min(100%,340px);max-height:calc(100dvh - 36px);overflow:auto;padding:20px;
      border-radius:12px;border:1px solid var(--line);background:var(--panel);box-shadow:0 8px 32px rgba(0,0,0,.16);color:var(--text);animation:dotDialogIn .18s ease-out}
    @keyframes dotDialogIn{from{opacity:0;transform:translateY(6px) scale(.98)}to{opacity:1;transform:translateY(0) scale(1)}}
    .dot-dialog-mark{display:none}
    .dot-dialog-title{font-size:17px;font-weight:700;margin:0 0 8px;color:var(--text)}
    .dot-dialog-message{font-size:14px;line-height:1.5;color:var(--muted);margin:0 0 16px;white-space:pre-wrap}
    .dot-dialog-input{display:block;width:100%;min-height:42px;padding:10px 12px;margin:0 0 16px;border:1px solid var(--line);border-radius:8px;background:var(--panel2);color:var(--text);resize:vertical;font-size:14px}
    .dot-dialog-input:focus{outline:none;border-color:var(--blue)}
    .dot-dialog-actions{display:flex;justify-content:flex-end;gap:8px}
    .dot-dialog-actions button{min-height:38px;padding:8px 16px;border-radius:6px;font-size:13px;font-weight:600}
    .dot-dialog-cancel{background:transparent;border:0;color:var(--muted)}
    .dot-dialog-ok{border:0;color:#fff;background:var(--blue)}
    .dot-dialog-ok.danger{background:var(--danger)}

    @media(min-width:700px){.app{border-left:1px solid var(--line);border-right:1px solid var(--line)}.auth-wrap{margin-top:8vh}}

    /* Image viewer */
    .modal-overlay{position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,.9);z-index:2147483647;display:flex;align-items:center;justify-content:center;padding:20px;opacity:0;pointer-events:none;transition:opacity .25s}
    .modal-overlay.active{opacity:1;pointer-events:auto}
    .modal-content{background:var(--panel);width:100%;max-width:400px;border-radius:12px;padding:22px;transform:translateY(20px);transition:transform .25s;box-shadow:0 8px 32px rgba(0,0,0,.2)}
    .modal-overlay.active .modal-content{transform:translateY(0)}
    .modal-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}
    .modal-header h3{margin:0;font-size:18px;font-weight:700}
    .close-modal{background:none;border:none;font-size:26px;color:var(--muted);cursor:pointer;padding:0;line-height:1}
    .modal-photo-section{display:flex;flex-direction:column;align-items:center;margin-bottom:16px}
    .modal-avatar{width:72px;height:72px;border-radius:50%;overflow:hidden;background:var(--panel2);margin-bottom:10px;position:relative;border:1px solid var(--line)}
    .modal-avatar img{width:100%;height:100%;object-fit:cover}
    .modal-avatar span{display:flex;width:100%;height:100%;align-items:center;justify-content:center;font-size:26px;font-weight:600}
    .modal-photo-actions{display:flex;gap:8px}

    /* Pull to refresh */
    .ptr-indicator{position:fixed;top:0;left:50%;transform:translateX(-50%) translateY(-70px);width:40px;height:40px;background:var(--panel);border:1px solid var(--line);
      border-radius:50%;display:flex;align-items:center;justify-content:center;box-shadow:0 2px 8px rgba(0,0,0,.08);z-index:9999;transition:transform .2s cubic-bezier(.175,.885,.32,1.275);pointer-events:none}
    .ptr-indicator svg{width:20px;height:20px;stroke:var(--blue);transition:transform .2s}
    .ptr-indicator.refreshing svg{animation:ptr-spin .8s linear infinite}
    .ptr-indicator.visible{transform:translateX(-50%) translateY(16px)}
    @keyframes ptr-spin{100%{transform:rotate(360deg)}}

    /* Wallpaper */
    .messages.custom-bg{background-size:cover!important;background-position:center!important;background-repeat:no-repeat!important}

    /* Double-tap heart */
    .double-tap-heart{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%) scale(0);color:#fff;font-size:80px;opacity:0;pointer-events:none;z-index:10;text-shadow:0 4px 15px rgba(0,0,0,.4);animation:likePop .6s ease-out forwards}
    @keyframes likePop{0%{transform:translate(-50%,-50%) scale(0);opacity:0}30%{transform:translate(-50%,-50%) scale(1.2);opacity:1}60%{transform:translate(-50%,-50%) scale(1);opacity:1}100%{transform:translate(-50%,-50%) scale(1.4);opacity:0}}
    .post-image{cursor:pointer}

    /* Emoji picker */
    .emoji-picker-container{position:absolute;bottom:60px;left:8px;background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:10px;
      display:grid;grid-template-columns:repeat(6,1fr);gap:6px;box-shadow:0 4px 24px rgba(0,0,0,.15);z-index:100;max-height:200px;overflow-y:auto}
    .emoji-picker-container span{cursor:pointer;font-size:20px;text-align:center;padding:4px;border-radius:4px;transition:background .15s}
    .emoji-picker-container span:hover{background:var(--panel2)}

    /* Carousel */
    .post-carousel{position:relative;width:100%;overflow:hidden;background:var(--panel2);display:flex;scroll-snap-type:x mandatory;overflow-x:auto;scrollbar-width:none}
    .post-carousel::-webkit-scrollbar{display:none}
    .post-carousel img{flex:0 0 100%;width:100%;max-height:520px;object-fit:cover;scroll-snap-align:center;cursor:pointer;-webkit-tap-highlight-color:transparent}
    .carousel-dots{position:absolute;bottom:10px;left:50%;transform:translateX(-50%);display:flex;gap:5px;z-index:2}
    .carousel-dot{width:6px;height:6px;border-radius:50%;background:rgba(255,255,255,.5)}
    .carousel-dot.active{background:#fff}
    .carousel-wrap{position:relative}

    /* Call UI — kept functional, simplified visual */
    .call-container{position:relative;width:100%;height:100%;display:flex;flex-direction:column;background:#000}
    .call-videos{flex:1;position:relative;display:flex;align-items:center;justify-content:center;overflow:hidden;background:#000}
    .remote-video{width:100%;height:100%;object-fit:cover;background:#111}
    .local-video{position:absolute;bottom:90px;right:16px;width:96px;height:140px;object-fit:cover;border-radius:10px;border:1px solid rgba(255,255,255,.4);z-index:10;box-shadow:0 4px 16px rgba(0,0,0,.5);background:#222}
    .call-status{position:absolute;top:16px;left:0;right:0;text-align:center;color:#fff;font-size:15px;font-weight:600;z-index:5;text-shadow:0 1px 4px rgba(0,0,0,.9)}
    .call-timer{position:absolute;top:42px;left:0;right:0;text-align:center;color:#9ad2ff;font-size:13px;font-weight:600;z-index:5;letter-spacing:1px}
    .call-actions{position:absolute;bottom:30px;left:0;right:0;display:flex;justify-content:center;gap:18px;z-index:10;padding:0 16px}
    .call-btn{width:54px;height:54px;border-radius:50%;border:none;font-size:22px;color:#fff;display:flex;align-items:center;justify-content:center;cursor:pointer;box-shadow:0 2px 8px rgba(0,0,0,.4);transition:transform .15s}
    .call-btn:active{transform:scale(.92)}
    .call-btn.end{background:#ed4956}
    .call-btn.accept{background:#34c759;animation:pulse 1.5s infinite}
    .call-btn.mute{background:rgba(255,255,255,.18)}
    .call-btn.mute.off{background:#ff9500}
    .call-btn.cam{background:rgba(255,255,255,.18)}
    .call-btn.cam.off{background:#ff9500}
    .call-btn.speaker{background:rgba(255,255,255,.18)}
    .call-btn.speaker.on{background:#1a73e8}
    .call-btn svg{display:block;pointer-events:none}
    .call-btn.mute.off svg,.call-btn.cam.off svg{fill:#fff}
    .call-btn.accept,.call-btn.end{color:#fff}
    @keyframes pulse{0%{transform:scale(1)}50%{transform:scale(1.08)}100%{transform:scale(1)}}

    /* Section divider for home */
    .feed-divider{height:8px;background:var(--panel2);margin:0 0 8px}

/* ---------- Mitra partner discovery ---------- */
.mitra-launch{margin:12px 0;padding:14px;border:1px solid var(--line);border-radius:12px;background:var(--panel)}
.mitra-launch button,.mitra-actions button{min-height:38px;padding:8px 12px;border-radius:8px;border:1px solid var(--line);background:var(--panel2);color:var(--text);font-weight:600}
.mitra-launch .primary,.mitra-actions .primary{background:var(--blue);color:#fff;border:0}
.mitra-panel{margin-top:12px}
.mitra-post{padding:14px 0;border-bottom:1px solid var(--line-soft)}
.mitra-post h3{font-size:15px;margin:5px 0}
.mitra-post p{font-size:13px;line-height:1.45;white-space:pre-wrap;overflow-wrap:anywhere;margin:6px 0}
.mitra-actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:10px}
.mitra-form{padding:12px;border:1px solid var(--line);border-radius:10px;margin:12px 0;background:var(--panel)}
.mitra-status{font-size:12px;color:var(--muted);min-height:18px;margin:8px 0}

b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;
// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }
      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }
      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };
      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
               + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };
      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;
      var onReply = function(commentId, domId) {
        if (replybox == null) {
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };
      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }
      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };
      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };
      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
//

body.script:
//
(function(){
  'use strict';
  var storage = null;
  var firebaseConfig = {
    apiKey: "AIzaSyAev5VMUVrwUBJijiDN5-EAmkBzB9EH4L0",
    authDomain: "dot-tag-89e39.firebaseapp.com",
    projectId: "dot-tag-89e39",
    storageBucket: "dot-tag-89e39.firebasestorage.app",
    messagingSenderId: "579943607333",
    appId: "1:579943607333:web:486d6d3bb12656b7b723cc"
  };
  var configured = firebaseConfig.apiKey.indexOf('PASTE_') !== 0;
  var appAuth = null, store = null, currentUser = null;
  var isSignup = false, activeChatId = null, activeOtherUid = null;
  var unsubscribeChats = null, unsubscribeMessages = null, unsubscribeOlderMsgs = null;
  var followCountsUnsubs = [];
  var unsubscribeNotifications = null, notificationRows = [];
  var unsubscribePosts = null, pendingPostImages = [];
  var pendingProfileImageUrl = null;
  var postLikeUnsubs = {}, likeActionBusy = {};
  var postPublishBusy = false, followActionBusy = false;
  var lastDocForPagination = null, feedLoadingMore = false;
  var onlineStatusTimer = null;
  var typingTimer = null, typingUnsub = null, typingClearTimer = null;
  var unsubscribePresence = null;
  var allChatsCache = [];
  var oldestMsgDoc = null, olderMsgLoading = false;
  var $ = function(id){return document.getElementById(id);};
  var views = ['authView','homeView','createPostView','chatsView','chatRoomView','exploreView','profileView','publicProfileView','notificationsView'];

  var localStream = null;
  var peerConnection = null;
  var currentCallId = null;
  var callDocRef = null;
  var callUnsubscribe = null;
  var incomingCallUnsubscribe = null;
  var remoteCandidateUnsub = null;
  var callerCandidateUnsub = null;
  var callTimerInterval = null;
  var callStartTime = null;
  var callTimeoutTimer = null;
  var callRole = null;
  var micMuted = false;
  var camOff = false;

  function showStatus(id,msg){ var el=$(id); if(el) el.textContent=msg||''; }
  function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
  function initials(s){s=String(s||'d.').trim();return s.charAt(0).toUpperCase()||'d.';}
  function profilePath(uid){return store.collection('profiles').doc(uid);}
  function postPath(){return store.collection('posts');}
  function notificationPath(){return store.collection('notifications');}
  function followPath(a,b){return store.collection('follows').doc(a+'_'+b);}
  function postLikesPath(postId){return postPath().doc(postId).collection('likes');}
  function userPresencePath(uid){return store.collection('presence').doc(uid);}
  function usernameReservePath(name){return store.collection('usernames').doc(name);}
  function callPath(id){return store.collection('calls').doc(id);}

  function processAndUploadImage(file, maxSize, qualityLimit, statusElId) {
    return new Promise(function(resolve, reject) {
      if(!file || !/^image\/(jpeg|png|webp|gif)$/i.test(file.type || '')) { reject(new Error('Choose a JPG, PNG, WEBP or GIF image.')); return; }
      if(file.size > 10 * 1024 * 1024) { reject(new Error('Photo must be smaller than 10 MB.')); return; }
      var reader = new FileReader();
      reader.onload = function(ev){
        var img = new Image();
        img.onload = function(){
          var scale = Math.min(1, maxSize / Math.max(img.width, img.height));
          var canvas = document.createElement('canvas');
          canvas.width = Math.max(1, Math.round(img.width * scale));
          canvas.height = Math.max(1, Math.round(img.height * scale));
          var ctx = canvas.getContext('2d'); ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
          var quality = 0.8, data = '';
          do{ data = canvas.toDataURL('image/jpeg', quality); quality -= 0.1; } while(data.length > qualityLimit && quality > 0.3);
          if(statusElId) showStatus(statusElId, 'Uploading image...');
          uploadToImgBB(data).then(resolve).catch(reject);
        };
        img.onerror = function() { reject(new Error('Invalid image file.')); };
        img.src = ev.target.result;
      };
      reader.onerror = function() { reject(new Error('Could not read file.')); };
      reader.readAsDataURL(file);
    });
  }

  var IMGBB_API_KEY = '7c60a162702b605afb125a8a634554fc';
  function uploadToImgBB(dataUrl){
    return new Promise(function(resolve, reject){
      if(!currentUser){ reject(new Error('Sign in before uploading images.')); return; }
      var base64 = String(dataUrl).split(',')[1];
      if(!base64){ reject(new Error('Could not prepare image data.')); return; }
      var form = new FormData();
      form.append('key', IMGBB_API_KEY);
      form.append('image', base64);
      form.append('name', 'dot_tag_' + Date.now());
      fetch('https://api.imgbb.com/1/upload', { method: 'POST', body: form })
        .then(function(r){ return r.json().then(function(j){ return { ok: r.ok, body: j }; }); })
        .then(function(res){
          if(res.ok && res.body && res.body.success && res.body.data && res.body.data.url){
            resolve(res.body.data.url);
          } else {
            var msg = (res.body && res.body.error && res.body.error.message) ? res.body.error.message : 'ImgBB upload failed.';
            reject(new Error(msg));
          }
        })
        .catch(function(e){ reject(new Error('ImgBB network error: ' + (e && e.message ? e.message : ''))); });
    });
  }

  function applyTheme(theme){
    document.documentElement.setAttribute('data-theme', theme);
    try{ localStorage.setItem('dot_theme', theme); }catch(e){}
    var btn = $('themeToggleBtn');
    if(btn) btn.textContent = theme === 'dark' ? 'Switch Theme ☀️' : 'Switch Theme 🌙';
  }
  function initTheme(){
    var saved = 'light';
    try{ saved = localStorage.getItem('dot_theme') || 'light'; }catch(e){}
    applyTheme(saved);
  }

  function startPresence(){
    if(!currentUser || !store) return;
    var ref = userPresencePath(currentUser.uid);
    ref.set({ online: true, lastSeen: firebase.firestore.FieldValue.serverTimestamp() }, { merge: true }).catch(function(){});
    if(onlineStatusTimer) clearInterval(onlineStatusTimer);
    onlineStatusTimer = setInterval(function(){
      if(currentUser) ref.set({ online: true, lastSeen: firebase.firestore.FieldValue.serverTimestamp() }, { merge: true }).catch(function(){});
    }, 60000);
    window.addEventListener('beforeunload', function(){
      if(currentUser) userPresencePath(currentUser.uid).set({ online: false, lastSeen: firebase.firestore.FieldValue.serverTimestamp() }, { merge: true });
    });
  }
  function stopPresence(){
    if(onlineStatusTimer){ clearInterval(onlineStatusTimer); onlineStatusTimer = null; }
    if(unsubscribePresence){ unsubscribePresence(); unsubscribePresence = null; }
    if(currentUser && store){
      userPresencePath(currentUser.uid).set({ online: false, lastSeen: firebase.firestore.FieldValue.serverTimestamp() }, { merge: true }).catch(function(){});
    }
  }
  function formatLastSeen(ts){
    try{
      if(!ts) return 'Offline';
      var d = ts.toDate ? ts.toDate() : new Date(ts);
      var diff = Math.floor((Date.now() - d.getTime())/60000);
      if(diff < 1) return 'Online';
      if(diff < 60) return 'Last seen ' + diff + 'm ago';
      if(diff < 1440) return 'Last seen ' + Math.floor(diff/60) + 'h ago';
      return 'Last seen ' + d.toLocaleDateString();
    }catch(e){ return 'Offline'; }
  }

  var profileMemCache = {}, profileCacheLoaded = false;
  function loadProfileCache(){
    if(profileCacheLoaded) return;
    try{ var raw = localStorage.getItem('dot_profile_cache'); if(raw) profileMemCache = JSON.parse(raw) || {}; }catch(e){ profileMemCache = {}; }
    profileCacheLoaded = true;
  }
  function saveProfileCache(){ try{ localStorage.setItem('dot_profile_cache', JSON.stringify(profileMemCache)); }catch(e){} }
  function getCachedProfile(uid){
    loadProfileCache();
    var cached = profileMemCache[uid], now = Date.now();
    if(cached && cached.ts && (now - cached.ts) < 300000) return Promise.resolve(cached.data);
    return profilePath(uid).get().then(function(doc){
      var data = doc.exists ? doc.data() : {};
      profileMemCache[uid] = { data: data, ts: now };
      saveProfileCache();
      return data;
    });
  }
  function invalidateProfileCache(uid){ if(profileMemCache[uid]){ delete profileMemCache[uid]; saveProfileCache(); } }

  var activeContextMenu = null;
  function closeContextMenu(){ if(activeContextMenu){ activeContextMenu.remove(); activeContextMenu = null; } }
  document.addEventListener('click', function(e){ if(activeContextMenu && !activeContextMenu.contains(e.target)) closeContextMenu(); });
  document.addEventListener('keydown', function(e){ if(e.key === 'Escape') closeContextMenu(); });
  function showContextMenu(x, y, items){
    closeContextMenu();
    var menu = document.createElement('div');
    menu.className = 'dot-context-menu';
    items.forEach(function(item){
      var b = document.createElement('button');
      b.type = 'button'; b.textContent = item.label;
      if(item.danger) b.className = 'danger';
      b.addEventListener('click', function(e){ e.stopPropagation(); closeContextMenu(); item.run(); });
      menu.appendChild(b);
    });
    document.body.appendChild(menu); activeContextMenu = menu;
    var w = menu.offsetWidth, h = menu.offsetHeight;
    menu.style.left = Math.max(8, Math.min(x, window.innerWidth - w - 8)) + 'px';
    menu.style.top = Math.max(8, Math.min(y, window.innerHeight - h - 8)) + 'px';
  }
  function attachLongPress(el, itemsFactory){
    var timer = null, suppressClick = false, sx = 0, sy = 0;
    function cancel(){ if(timer){ clearTimeout(timer); timer = null; } }
    el.addEventListener('click', function(e){ if(suppressClick){ suppressClick = false; e.preventDefault(); e.stopPropagation(); } }, true);
    el.addEventListener('contextmenu', function(e){ e.preventDefault(); e.stopPropagation(); showContextMenu(e.clientX || sx, e.clientY || sy, itemsFactory()); });
    el.addEventListener('touchstart', function(e){
      if(!e.touches || !e.touches[0]) return;
      cancel(); sx = e.touches[0].clientX; sy = e.touches[0].clientY;
      timer = setTimeout(function(){ timer = null; suppressClick = true; showContextMenu(sx, sy, itemsFactory()); }, 600);
    }, {passive:true});
    el.addEventListener('touchmove', function(e){
      if(!timer || !e.touches || !e.touches[0]) return;
      if(Math.abs(e.touches[0].clientX - sx) > 12 || Math.abs(e.touches[0].clientY - sy) > 12) cancel();
    }, {passive:true});
    el.addEventListener('touchend', cancel, {passive:true});
    el.addEventListener('touchcancel', cancel, {passive:true});
  }

  var dotDialogActive = null;
  function closeDotDialog(value){
    if(!dotDialogActive) return;
    var a = dotDialogActive; dotDialogActive = null;
    document.removeEventListener('keydown', a.keyHandler);
    if(a.backdrop.parentNode) a.backdrop.parentNode.removeChild(a.backdrop);
    if(a.resolve) a.resolve(value);
  }
  function dotDialog(opts){
    opts = opts || {};
    return new Promise(function(resolve){
      if(dotDialogActive) closeDotDialog(null);
      var backdrop = document.createElement('div');
      backdrop.className = 'dot-dialog-backdrop';
      var panel = document.createElement('section');
      panel.className = 'dot-dialog';
      panel.setAttribute('role', opts.type === 'alert' ? 'alertdialog' : 'dialog');
      var title = document.createElement('h2'); title.className = 'dot-dialog-title'; title.textContent = opts.title || 'Notice';
      var msg = document.createElement('p'); msg.className = 'dot-dialog-message'; msg.textContent = opts.message || '';
      panel.appendChild(title); panel.appendChild(msg);
      var field = null;
      if(opts.type === 'prompt'){
        field = document.createElement(opts.multiline ? 'textarea' : 'input');
        field.className = 'dot-dialog-input';
        if(opts.multiline){ field.rows = 4; field.maxLength = 1800; } else { field.type = opts.inputType || 'text'; field.maxLength = opts.maxLength || 100; }
        field.value = opts.value || ''; panel.appendChild(field);
      }
      var actions = document.createElement('div'); actions.className = 'dot-dialog-actions';
      if(opts.type !== 'alert'){
        var cancel = document.createElement('button');
        cancel.type = 'button'; cancel.className = 'dot-dialog-cancel'; cancel.textContent = 'Cancel';
        cancel.addEventListener('click', function(){ closeDotDialog(opts.type === 'prompt' ? null : false); });
        actions.appendChild(cancel);
      }
      var ok = document.createElement('button');
      ok.type = 'button'; ok.className = 'dot-dialog-ok' + (opts.danger ? ' danger' : ''); ok.textContent = opts.okText || 'OK';
      ok.addEventListener('click', function(){ closeDotDialog(opts.type === 'prompt' ? field.value : true); });
      actions.appendChild(ok); panel.appendChild(actions); backdrop.appendChild(panel);
      backdrop.addEventListener('click', function(e){ if(e.target === backdrop && opts.type !== 'alert') closeDotDialog(opts.type === 'prompt' ? null : false); });
      var keyHandler = function(e){
        if(e.key === 'Escape' && opts.type !== 'alert'){ closeDotDialog(opts.type === 'prompt' ? null : false); }
        else if(e.key === 'Enter' && opts.type === 'prompt' && field && !opts.multiline){ e.preventDefault(); ok.click(); }
      };
      dotDialogActive = { backdrop: backdrop, resolve: resolve, keyHandler: keyHandler };
      document.addEventListener('keydown', keyHandler);
      document.body.appendChild(backdrop);
      if(field){ field.focus(); if(field.select) field.select(); } else ok.focus();
    });
  }
  function dotAlert(m, t){ return dotDialog({type:'alert', title:t||'Notice', message:String(m||'')}); }
  function dotConfirm(m, t, d){ return dotDialog({type:'confirm', title:t||'Confirm', message:m, okText:d?'Delete':'Continue', danger:!!d}); }
  function dotPrompt(m, v, t){ return dotDialog({type:'prompt', title:t||'Edit', message:m, value:v||'', multiline:true, okText:'Save', maxLength:1800}); }
  function confirmDelete(label){ return dotConfirm('Delete this ' + label + '?', 'Confirm deletion', true); }

  function showView(id){
    $('bootScreen').classList.add('hidden');
    views.forEach(function(v){ $(v).classList.toggle('hidden', v !== id); });
    $('mainTopbar').classList.toggle('hidden', id === 'authView' || id === 'chatRoomView');
    $('bottomNav').classList.toggle('hidden', !currentUser || id === 'chatRoomView');
    document.querySelectorAll('.nav-btn[data-view]').forEach(function(b){ b.classList.toggle('active', b.getAttribute('data-view') === id); });
    window.scrollTo(0,0);
    var ptr = $('ptrIndicator');
    if (ptr) { ptr.classList.remove('visible', 'refreshing'); ptr.style.transform = 'translateX(-50%) translateY(-70px)'; }
    if(id === 'homeView' && currentUser && !unsubscribePosts) listenPosts();
  }

  function openImageViewer(url) {
    if(!url) return;
    $('fullImageViewer').src = url;
    $('imageViewerModal').classList.add('active');
  }
  $('closeImageViewer').onclick = function() { $('imageViewerModal').classList.remove('active'); };
  $('imageViewerModal').onclick = function(e) { if(e.target === this) this.classList.remove('active'); };
  $('messages').addEventListener('click', function(e) {
    if(e.target.classList.contains('bubble-image')) openImageViewer(e.target.src);
  });

  function notificationTime(ts){ try{ if(!ts) return 'Just now'; var d = ts.toDate ? ts.toDate() : new Date(ts); return d.toLocaleString(); }catch(e){ return 'Recent'; } }
  function formatPostTime(ts){ try{ if(!ts) return 'Just now'; var d = ts.toDate ? ts.toDate() : new Date(ts); return d.toLocaleString(); }catch(e){ return 'Recently'; } }
  function formatMessageTime(ts){
    try{
      if(!ts) return '';
      var d = ts.toDate ? ts.toDate() : new Date(ts);
      var now = new Date();
      var today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
      var msgDay = new Date(d.getFullYear(), d.getMonth(), d.getDate());
      var diffDays = Math.floor((today - msgDay) / 86400000);
      var hours = d.getHours(), minutes = d.getMinutes();
      var ampm = hours >= 12 ? 'PM' : 'AM';
      hours = hours % 12; if(hours === 0) hours = 12;
      var timeStr = hours + ':' + (minutes < 10 ? '0' + minutes : minutes) + ' ' + ampm;
      if(diffDays === 0) return timeStr;
      if(diffDays === 1) return 'Yesterday ' + timeStr;
      if(diffDays < 7){ var days = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat']; return days[d.getDay()] + ' ' + timeStr; }
      var day = d.getDate(), months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
      var month = months[d.getMonth()], year = d.getFullYear();
      if(year === now.getFullYear()) return day + ' ' + month + ' ' + timeStr;
      return day + ' ' + month + ' ' + year + ' ' + timeStr;
    }catch(e){ return ''; }
  }

  function loadFollowCounts(uid){
    if(!store || !uid) return;
    followCountsUnsubs.forEach(function(u){ try{u();}catch(e){} }); followCountsUnsubs = [];
    followCountsUnsubs.push(store.collection('follows').where('followingId','==',uid).onSnapshot(function(s){
      $('statFollowers').textContent = String(s.docs.filter(function(d){ return d.data().status === 'accepted'; }).length);
    }, function(){ $('statFollowers').textContent = '—'; }));
    followCountsUnsubs.push(store.collection('follows').where('followerId','==',uid).onSnapshot(function(s){
      $('statFollowing').textContent = String(s.docs.filter(function(d){ return d.data().status === 'accepted'; }).length);
    }, function(){ $('statFollowing').textContent = '—'; }));
  }

  function renderFollowButton(targetUid, container){
    if(!container || !currentUser || targetUid === currentUser.uid) return;
    var btn = container.querySelector('[data-follow-button]'); if(!btn) return;
    btn.disabled = true; btn.textContent = 'Checking…';
    getCachedProfile(targetUid).then(function(targetProfile){
      var isPrivate = targetProfile.isPrivate === true;
      followPath(currentUser.uid, targetUid).get().then(function(doc){
        var following = doc.exists;
        var status = doc.exists ? doc.data().status : null;
        btn.disabled = false;
        if (following) {
          if (status === 'pending') { btn.textContent = 'Requested'; btn.classList.add('following'); }
          else { btn.textContent = 'Following'; btn.classList.add('following'); }
        } else {
          btn.textContent = 'Follow'; btn.classList.remove('following');
        }
        btn.onclick = function(){
          if(followActionBusy) return;
          followActionBusy = true; btn.disabled = true;
          var ref = followPath(currentUser.uid, targetUid);
          if(following){
            ref.delete().then(function(){
              following = false; status = null;
              btn.textContent = 'Follow'; btn.classList.remove('following');
              loadFollowCounts(currentUser.uid);
            }).catch(function(e){ dotAlert('Failed: ' + e.message); }).then(function(){ btn.disabled = false; followActionBusy = false; });
          } else {
            var newStatus = isPrivate ? 'pending' : 'accepted';
            ref.set({ followerId: currentUser.uid, followingId: targetUid, status: newStatus, createdAt: firebase.firestore.FieldValue.serverTimestamp() })
              .then(function(){
                following = true; status = newStatus;
                btn.textContent = isPrivate ? 'Requested' : 'Following';
                btn.classList.add('following');
                loadFollowCounts(currentUser.uid);
                if(isPrivate) return createNotification({recipientId: targetUid, actorId: currentUser.uid, type: 'follow_request'});
                return createNotification({recipientId: targetUid, actorId: currentUser.uid, type: 'follow'});
              }).catch(function(e){ dotAlert('Failed: ' + e.message); }).then(function(){ btn.disabled = false; followActionBusy = false; });
          }
        };
      });
    }).catch(function(){ btn.disabled = true; btn.textContent = 'Error'; });
  }

  function loadFollowList(kind, targetUid, isPublic){
    if(!currentUser || !store) return;
    var uid = targetUid || currentUser.uid, field = kind === 'followers' ? 'followingId' : 'followerId';
    var card = $(isPublic ? 'publicFollowListCard' : 'followListCard');
    var title = $(isPublic ? 'publicFollowListTitle' : 'followListTitle');
    var box = $(isPublic ? 'publicFollowListContent' : 'followListContent');
    card.classList.remove('hidden');
    title.textContent = kind === 'followers' ? 'Followers' : 'Following';
    box.textContent = 'Loading…';
    store.collection('follows').where(field,'==',uid).limit(50).get().then(function(snap){
      box.innerHTML = '';
      if(snap.empty){ box.innerHTML = '<div class="empty">No ' + kind + ' yet.</div>'; return; }
      var uids = snap.docs.filter(function(d){ return d.data().status === 'accepted'; }).map(function(d){ var f = d.data(); return kind === 'followers' ? f.followerId : f.followingId; }).filter(function(x){ return x && x !== uid; });
      return Promise.all(uids.map(function(u){ return getCachedProfile(u).then(function(p){ return { uid: u, p: p }; }); })).then(function(rows){
        box.innerHTML = '';
        rows.forEach(function(row){
          var p = row.p, n = p.displayName || p.username || 'dot.tag user', handle = p.username || 'user';
          var r = document.createElement('div'); r.className = 'follow-list-row';
          var avatar = p.profileImage ? '<img alt="" src="' + esc(p.profileImage) + '" />' : esc(initials(n));
          r.innerHTML = '<div class="avatar">' + avatar + '</div><div class="grow"><strong class="truncate" style="font-size:14px">' + esc(n) + '</strong><div class="muted small truncate">@' + esc(handle) + '</div></div><div class="follow-list-actions"><button class="secondary" type="button">View</button></div>';
          var open = function(){ card.classList.add('hidden'); openPublicProfile(row.uid, isPublic ? 'publicProfileView' : 'profileView'); };
          r.querySelector('.grow').addEventListener('click', open);
          r.querySelector('.avatar').style.cursor = 'pointer';
          r.querySelector('.avatar').addEventListener('click', open);
          r.querySelector('.follow-list-actions button').addEventListener('click', open);
          box.appendChild(r);
        });
        if(!rows.length) box.innerHTML = '<div class="empty">No ' + kind + ' to show.</div>';
      });
    }).catch(function(e){ box.textContent = 'Could not load: ' + e.message; });
  }

  function setProfile(user, profile){
    var name = (profile && profile.displayName) || user.displayName || 'dot.tag user';
    var handle = (profile && profile.username) || 'user';
    $('helloName').textContent = name;
    $('profileName').textContent = name;
    $('profileHandle').textContent = '@' + handle;
    $('profileEmail').textContent = user.email || '';

    var avatarInner = $('profileAvatar');
    var photo = (profile && profile.profileImage) || '';
    if(photo) avatarInner.innerHTML = '<img alt="" src="' + esc(photo) + '" />';
    else avatarInner.innerHTML = '<span>' + esc(initials(name)) + '</span>';

    var modalAvatar = $('modalAvatarPreview');
    if(photo) modalAvatar.innerHTML = '<img alt="" src="' + esc(photo) + '" />';
    else modalAvatar.innerHTML = '<span>' + esc(initials(name)) + '</span>';

    $('profileBio').textContent = (profile && profile.bio) || 'Add a short bio about yourself.';
    if(user && user.uid === currentUser.uid) {
      loadFollowCounts(user.uid);
      loadProfilePosts(user.uid, false);
    }
    $('editDisplayName').value = name;
    $('editBio').value = (profile && profile.bio) || '';
    $('editIsPrivate').checked = (profile && profile.isPrivate === true);
  }

  function loadProfilePosts(uid, isPublic) {
    var grid = $(isPublic ? 'publicPostsGrid' : 'profilePostsGrid');
    if (!grid) return;
    grid.innerHTML = '<div class="empty" style="grid-column:1/-1;padding:20px;">Loading...</div>';
    postPath().where('authorId', '==', uid).orderBy('createdAt', 'desc').limit(30).get().then(function(snap) {
      grid.innerHTML = '';
      if (snap.empty) {
        grid.innerHTML = '<div class="empty" style="grid-column:1/-1;padding:20px;">No posts yet.</div>'; return;
      }
      snap.docs.forEach(function(doc) {
        var d = doc.data();
        var imgUrls = d.imageUrls || (d.imageUrl ? [d.imageUrl] : []);
        var imgSrc = imgUrls[0] || '';
        var postDiv = document.createElement('div');
        postDiv.style.cssText = 'aspect-ratio:1/1;position:relative;background:var(--panel2);overflow:hidden;cursor:pointer;';
        if (imgSrc) {
          postDiv.innerHTML = '<img src="' + esc(imgSrc) + '" style="width:100%;height:100%;object-fit:cover;" loading="lazy"/>';
        } else {
          postDiv.innerHTML = '<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;padding:10px;font-size:11px;color:var(--muted);text-align:center;background:var(--panel2);">' + esc(d.text || 'Text Post') + '</div>';
        }
        postDiv.onclick = function() { if(imgSrc) openImageViewer(imgSrc); };
        grid.appendChild(postDiv);
      });
    }).catch(function(e) {
      console.warn('Profile posts index required:', e);
      grid.innerHTML = '<div class="empty" style="grid-column:1/-1;padding:20px;font-size:11px;">Could not load posts.</div>';
    });
  }

  var publicProfileUid = null, publicProfileBackView = 'exploreView';
  function openPublicProfile(uid, backView){
    if(!currentUser || !uid) return;
    if(uid === currentUser.uid){ showView('profileView'); return; }
    publicProfileUid = uid; publicProfileBackView = backView || 'exploreView';
    $('publicFollowListCard').classList.add('hidden');
    $('publicName').textContent = 'Loading…'; $('publicHandle').textContent = ''; $('publicBio').textContent = '';
    $('publicAvatar').textContent = 'd.';
    $('publicFollowBtn').disabled = true; $('publicMessageBtn').disabled = true;
    showView('publicProfileView');
    getCachedProfile(uid).then(function(p){
      if(!p || !Object.keys(p).length){ $('publicName').textContent = 'Profile not found'; return; }
      var name = p.displayName || p.username || 'dot.tag user';
      $('publicName').textContent = name + (p.isPrivate ? ' 🔒' : '');
      $('publicHandle').textContent = '@' + (p.username || 'user');
      $('publicBio').textContent = p.bio || 'No bio yet.';
      if(p.profileImage) $('publicAvatar').innerHTML = '<img alt="" src="' + esc(p.profileImage) + '" />';
      else $('publicAvatar').textContent = initials(name);
      $('publicFollowBtn').disabled = false; $('publicMessageBtn').disabled = false;
      renderFollowButton(uid, $('publicProfileView'));
      Promise.all([
        store.collection('follows').where('followingId','==',uid).get(),
        store.collection('follows').where('followerId','==',uid).get()
      ]).then(function(c){
        $('publicFollowers').textContent = String(c[0].docs.filter(function(d){ return d.data().status === 'accepted'; }).length);
        $('publicFollowing').textContent = String(c[1].docs.filter(function(d){ return d.data().status === 'accepted'; }).length);
      }).catch(function(){});
      var isTargetPrivate = p.isPrivate === true;
      var isFollowing = false;

      followPath(currentUser.uid, uid).get().then(function(fDoc){
        if (fDoc.exists && fDoc.data().status === 'accepted') {
          isFollowing = true;
        }
        if (isTargetPrivate && !isFollowing) {
          $('publicPosts').textContent = '🔒';
          $('publicPostsGrid').innerHTML = '<div class="empty" style="grid-column:1/-1;padding:30px 10px;text-align:center;"><div class="big">🔒</div><strong>This account is private</strong><p>Follow this account to see their photos and posts.</p></div>';
          $('publicMessageBtn').disabled = true;
          $('publicMessageBtn').textContent = 'Follow to Message';
          $('publicMessageBtn').style.opacity = '0.5';
        } else {
          postPath().where('authorId','==',uid).limit(50).get().then(function(posts){
            $('publicPosts').textContent = String(posts.size);
            loadProfilePosts(uid, true);
          }).catch(function(){ $('publicPosts').textContent = '0'; });
          $('publicMessageBtn').disabled = false;
          $('publicMessageBtn').textContent = 'Message';
          $('publicMessageBtn').style.opacity = '1';
        }
      });

      $('publicMessageBtn').onclick = function(){
        if(!currentUser || !publicProfileUid) return;
        if (isTargetPrivate && !isFollowing) {
          dotAlert('You cannot message this account until they accept your follow request.', 'Private Account');
          return;
        }
        var target = publicProfileUid, ids = [currentUser.uid, target].sort(), chatId = ids.join('_');
        var ref = store.collection('chats').doc(chatId);
        ref.get().then(function(d){
          return d.exists ? null : ref.set({ participants: ids, createdAt: firebase.firestore.FieldValue.serverTimestamp(), updatedAt: firebase.firestore.FieldValue.serverTimestamp(), lastMessage: '', lastSenderId: '' });
        }).then(function(){ openChat(chatId, target, name); })
          .catch(function(e){ dotAlert('Could not open chat: ' + e.message); });
      };
    });
  }

  function openCreatePost(){
    if(!currentUser){ showView('authView'); return; }
    pendingPostImages = [];
    $('postText').value = ''; $('postImageInput').value = '';
    $('postImagePreview').src = ''; $('postImagePreview').classList.add('hidden');
    $('removePostImage').classList.add('hidden');
    showStatus('postCreateStatus','');
    showView('createPostView');
  }

  function renderPostCard(doc, prepend){
    var d = doc.data() || {};
    var name = d.authorName || 'dot.tag user', handle = d.authorUsername || 'user';
    var avatar = d.authorPhoto ? '<img alt="" src="' + esc(d.authorPhoto) + '" />' : esc(initials(name));
    var el = document.createElement('article'); el.className = 'feed-post';
    var head = '<div class="post-meta"><div class="avatar">' + avatar + '</div><div class="grow"><strong>' + esc(name) + '</strong><div class="muted small">@' + esc(handle) + ' · ' + esc(formatPostTime(d.createdAt)) + '</div></div>' + (d.authorId === currentUser.uid ? '<span class="pill">YOU</span>' : '') + '</div>';

    var imgUrls = d.imageUrls || (d.imageUrl ? [d.imageUrl] : []);
    var image = '';
    if (imgUrls.length === 1) {
      image = '<div class="carousel-wrap"><img class="post-image" alt="" loading="lazy" src="' + esc(imgUrls[0]) + '"/></div>';
    } else if (imgUrls.length > 1) {
      image = '<div class="carousel-wrap"><div class="post-carousel">';
      imgUrls.forEach(function(u, index) {
        image += '<img alt="" loading="lazy" src="' + esc(u) + '" class="carousel-img" data-index="' + index + '"/>';
      });
      image += '</div><div class="carousel-dots">';
      imgUrls.forEach(function(u, index) {
        image += '<div class="carousel-dot' + (index === 0 ? ' active' : '') + '"></div>';
      });
      image += '</div></div>';
    }
    var copy = d.text ? '<div class="post-text">' + esc(d.text) + '</div>' : '';
    var actions = '<div class="post-actions"><button type="button" class="like-btn" data-post-id="' + esc(doc.id) + '"><span class="heart">♡</span><span class="like-label" style="display:none">Like</span><span class="like-count">0</span></button>' + (d.authorId === currentUser.uid ? '<div class="post-owner-actions"><button type="button" class="post-more-btn" aria-label="Options">⋯</button></div>' : '') + '</div>';
    el.innerHTML = head + image + copy + actions;

    watchPostLikes(doc.id, el);
    el.querySelector('.like-btn').addEventListener('click', function(){ togglePostLike(doc.id, el); });

    if(imgUrls.length > 0) {
      var imgs = el.querySelectorAll('.post-image, .carousel-img');
      imgs.forEach(function(img) {
        var lastTap = 0, tapTimeout = null, touchStartX = 0, touchStartY = 0, isDragging = false;
        img.addEventListener('touchstart', function(e) {
          isDragging = false;
          if(e.touches && e.touches[0]) { touchStartX = e.touches[0].clientX; touchStartY = e.touches[0].clientY; }
        }, {passive: true});
        img.addEventListener('touchmove', function(e) {
          if(e.touches && e.touches[0]) {
            if(Math.abs(e.touches[0].clientX - touchStartX) > 10 || Math.abs(e.touches[0].clientY - touchStartY) > 10) isDragging = true;
          }
        }, {passive: true});
        img.addEventListener('click', function(e) {
          if (isDragging) return;
          var currentTime = Date.now();
          var tapLength = currentTime - lastTap;
          var currentImgSrc = this.src;
          if (tapLength < 300 && tapLength > 0) {
            clearTimeout(tapTimeout);
            var heart = document.createElement('div');
            heart.className = 'double-tap-heart';
            heart.textContent = '❤️';
            img.parentNode.style.position = 'relative';
            img.parentNode.appendChild(heart);
            setTimeout(function() { heart.remove(); }, 800);
            var btn = el.querySelector('.like-btn');
            if(btn && !btn.classList.contains('liked')) togglePostLike(doc.id, el);
          } else {
            tapTimeout = setTimeout(function() { openImageViewer(currentImgSrc); }, 250);
          }
          lastTap = currentTime;
        });
      });
    }

    if (imgUrls.length > 1) {
      var carousel = el.querySelector('.post-carousel');
      var dots = el.querySelectorAll('.carousel-dot');
      carousel.addEventListener('scroll', function() {
        var width = carousel.clientWidth;
        var activeIndex = Math.round(carousel.scrollLeft / width);
        dots.forEach(function(dot, i){ dot.classList.toggle('active', i === activeIndex); });
      });
    }

    if(d.authorId === currentUser.uid){
      var more = el.querySelector('.post-more-btn');
      if(more) more.addEventListener('click', function(e){
        e.stopPropagation();
        showContextMenu(e.clientX || window.innerWidth - 170, e.clientY || 120, [
          {label:'Edit post', run:function(){ editOwnPost(doc.id, d.authorId, d.text || ''); }},
          {label:'Delete post', danger:true, run:function(){ deleteOwnPost(doc.id, d.authorId); }}
        ]);
      });
    }
    var feed = $('postFeed');
    if(prepend && feed.firstChild) feed.insertBefore(el, feed.firstChild);
    else feed.appendChild(el);
  }

  function listenPosts(){
    if(unsubscribePosts){ unsubscribePosts(); unsubscribePosts = null; }
    clearPostLikeListeners();
    if(!store || !currentUser) return;
    showStatus('feedStatus','Loading posts…');
    lastDocForPagination = null;
    store.collection('follows').where('followerId','==',currentUser.uid).get().then(function(followSnap){
      var authorIds = followSnap.docs.filter(function(d){return d.data().status === 'accepted';}).map(function(d){return d.data().followingId;});
      authorIds.push(currentUser.uid);
      authorIds = Array.from(new Set(authorIds)).slice(0,100);
      var byAuthor = {}, unsubs = [], failed = false;
      function renderMerged(){
        var docs=[]; Object.keys(byAuthor).forEach(function(uid){docs=docs.concat(byAuthor[uid]||[]);});
        docs.sort(function(a,b){var ad=a.data().createdAt&&a.data().createdAt.toMillis?a.data().createdAt.toMillis():0;var bd=b.data().createdAt&&b.data().createdAt.toMillis?b.data().createdAt.toMillis():0;return bd-ad;});
        var seen={}; docs=docs.filter(function(d){if(seen[d.id])return false;seen[d.id]=true;return true;}).slice(0,30);
        var box=$('postFeed'); box.innerHTML='';
        if(!docs.length){box.innerHTML='<div class="empty"><div class="big">🌱</div><strong>No posts yet</strong><p>Follow people to see their posts, or share your first post.</p></div>';}
        else docs.forEach(function(doc){renderPostCard(doc,false);});
        $('loadMorePosts').classList.add('hidden');
        showStatus('feedStatus','');
      }
      authorIds.forEach(function(uid){
        var unsub=postPath().where('authorId','==',uid).orderBy('createdAt','desc').limit(30).onSnapshot(function(snap){byAuthor[uid]=snap.docs;renderMerged();},function(e){if(!failed){failed=true;showStatus('feedStatus','Could not load posts: '+(e.message||''));}});
        unsubs.push(unsub);
      });
      unsubscribePosts=function(){unsubs.forEach(function(u){try{u();}catch(e){}});};
    }).catch(function(e){showStatus('feedStatus','Could not load feed: '+(e.message||''));});
  }

  $('loadMorePosts').addEventListener('click', function(){
    if(!currentUser || !store || feedLoadingMore || !lastDocForPagination) return;
    feedLoadingMore = true;
    this.textContent = 'Loading…';
    Promise.all([
      store.collection('follows').where('followerId','==',currentUser.uid).get(),
      postPath().orderBy('createdAt','desc').startAfter(lastDocForPagination).limit(15).get()
    ]).then(function(results){
      var allowed = results[0].docs.filter(function(d){ return d.data().status === 'accepted'; }).map(function(d){ return d.data().followingId; });
      allowed.push(currentUser.uid);
      var snap = results[1];
      return Promise.all(snap.docs.map(function(doc){
        var d = doc.data();
        return getCachedProfile(d.authorId).then(function(profile){
          return (d.authorId === currentUser.uid || !profile || profile.isPrivate !== true || allowed.indexOf(d.authorId) !== -1) ? doc : null;
        });
      })).then(function(filtered){
        filtered.forEach(function(doc){ if(doc) renderPostCard(doc, false); });
        if(snap.docs.length) lastDocForPagination = snap.docs[snap.docs.length - 1];
        $('loadMorePosts').classList.toggle('hidden', snap.size < 15);
      });
    }).catch(function(e){ dotAlert('Could not load more: ' + e.message); })
    .then(function(){ feedLoadingMore = false; $('loadMorePosts').textContent = 'Load more posts'; });
  });

  function watchPostLikes(postId, el){
    if(postLikeUnsubs[postId]){ postLikeUnsubs[postId](); delete postLikeUnsubs[postId]; }
    postLikeUnsubs[postId] = postLikesPath(postId).onSnapshot(function(snap){
      if(!el || !el.isConnected) return;
      var btn = el.querySelector('.like-btn'); if(!btn) return;
      var liked = snap.docs.some(function(d){ return d.id === currentUser.uid; });
      btn.classList.toggle('liked', liked);
      btn.querySelector('.heart').textContent = liked ? '♥' : '♡';
      btn.querySelector('.like-label').textContent = liked ? 'Liked' : 'Like';
      btn.querySelector('.like-count').textContent = String(snap.size);
    }, function(){});
  }
  function togglePostLike(postId, el){
    if(!currentUser || !store){ showView('authView'); return; }
    if(likeActionBusy[postId]) return;
    likeActionBusy[postId] = true;
    var btn = el.querySelector('.like-btn'); if(btn) btn.disabled = true;
    var ref = postLikesPath(postId).doc(currentUser.uid);
    ref.get().then(function(doc){
      if(doc.exists) return ref.delete();
      return ref.set({ userId: currentUser.uid, createdAt: firebase.firestore.FieldValue.serverTimestamp() });
    }).catch(function(e){ dotAlert('Like failed: ' + e.message); })
      .then(function(){ likeActionBusy[postId] = false; if(btn && btn.isConnected) btn.disabled = false; },
            function(){ likeActionBusy[postId] = false; if(btn && btn.isConnected) btn.disabled = false; });
  }
  function clearPostLikeListeners(){ Object.keys(postLikeUnsubs).forEach(function(id){ try{ postLikeUnsubs[id](); }catch(e){} }); postLikeUnsubs = {}; }

  function deleteOwnPost(postId, authorId){
    if(!currentUser || authorId !== currentUser.uid){ dotAlert('You can delete only your own post.'); return; }
    confirmDelete('post').then(function(ok){
      if(!ok) return;
      postPath().doc(postId).delete().then(function(){ showStatus('feedStatus','Post deleted.'); }).catch(function(e){ dotAlert('Failed: ' + e.message); });
    });
  }
  function editOwnPost(postId, authorId, oldText){
    if(!currentUser || authorId !== currentUser.uid){ dotAlert('You can edit only your own post.'); return; }
    dotPrompt('Update the text of your post:', oldText || '', 'Edit post').then(function(next){
      if(next === null) return;
      next = String(next).trim();
      if(!next){ dotAlert('Post text cannot be empty.'); return; }
      if(next === (oldText || '')) return;
      postPath().doc(postId).get().then(function(doc){
        if(!doc.exists || doc.data().authorId !== currentUser.uid) throw new Error('Post ownership could not be verified.');
        return doc.ref.update({ text: next, editedAt: firebase.firestore.FieldValue.serverTimestamp() });
      }).then(function(){ showStatus('feedStatus','Post updated.'); }).catch(function(e){ dotAlert('Failed: ' + e.message); });
    });
  }

  function publishPost(){
    if(!currentUser || !store || postPublishBusy) return;
    var text = $('postText').value.trim();
    var hasImage = pendingPostImages.length > 0;
    if(!text && !hasImage){ showStatus('postCreateStatus','Write something or add a photo first.'); return; }
    if(text.length > 1800){ showStatus('postCreateStatus','Post text must be 1,800 characters or fewer.'); return; }
    postPublishBusy = true; $('publishPost').disabled = true;
    showStatus('postCreateStatus', hasImage ? 'Uploading photos…' : 'Publishing…');
    getCachedProfile(currentUser.uid).then(function(p){
      var data = {
        authorId: currentUser.uid,
        authorName: p.displayName || currentUser.displayName || 'dot.tag user',
        authorUsername: p.username || 'user',
        text: text,
        createdAt: firebase.firestore.FieldValue.serverTimestamp()
      };
      if(p.profileImage) data.authorPhoto = p.profileImage;
      if(pendingPostImages.length > 0) data.imageUrls = pendingPostImages;
      return postPath().add(data);
    }).then(function(){
      pendingPostImages = [];
      $('postText').value = ''; $('postImageInput').value = '';
      $('postImagePreview').src = ''; $('postImagePreview').classList.add('hidden');
      $('removePostImage').classList.add('hidden');
      showView('homeView');
      showStatus('feedStatus','Post published!');
    }).catch(function(e){
      showStatus('postCreateStatus','Could not publish: ' + (e.message || ''));
    }).then(function(){ postPublishBusy = false; $('publishPost').disabled = false; });
  }
  function bootFirebase(){
    if(!configured){ showStatus('authStatus','Firebase not configured.'); return false; }
    if(!window.firebase){ showStatus('authStatus','Firebase scripts did not load.'); return false; }
    if(!firebase.apps.length) firebase.initializeApp(firebaseConfig);
    appAuth = firebase.auth(); store = firebase.firestore(); storage = firebase.storage(); return true;
  }

  function startApp(user){
    currentUser = user;
    getCachedProfile(user.uid).then(function(profile){
      if(!profile || !profile.username){
        return profilePath(user.uid).set({
          displayName: user.displayName || 'dot.tag user',
          username: 'user_' + user.uid.substring(0,8).toLowerCase(),
          createdAt: firebase.firestore.FieldValue.serverTimestamp()
        }).then(function(){
          invalidateProfileCache(user.uid);
          return getCachedProfile(user.uid);
        }).then(function(p){ setProfile(user, p); });
      }
      setProfile(user, profile);
    }).catch(function(e){ console.error(e); setProfile(user, {}); });
    showView('homeView');
    listenChats(); listenPosts(); loadFollowCounts(user.uid); listenNotifications();
    startPresence();
    listenForIncomingCalls();
  }

  function stopListeners(){
    followCountsUnsubs.forEach(function(u){ try{u();}catch(e){} }); followCountsUnsubs = [];
    if(unsubscribeChats){ unsubscribeChats(); unsubscribeChats = null; }
    if(unsubscribeMessages){ unsubscribeMessages(); unsubscribeMessages = null; }
    if(unsubscribeOlderMsgs){ unsubscribeOlderMsgs(); unsubscribeOlderMsgs = null; }
    if(unsubscribeNotifications){ unsubscribeNotifications(); unsubscribeNotifications = null; }
    if(unsubscribePosts){ unsubscribePosts(); unsubscribePosts = null; }
    if(typingUnsub){ typingUnsub(); typingUnsub = null; }
    if(typingTimer){ clearTimeout(typingTimer); typingTimer = null; }
    if(typingClearTimer){ clearTimeout(typingClearTimer); typingClearTimer = null; }
    clearPostLikeListeners();
    stopPresence();
    if(incomingCallUnsubscribe) { incomingCallUnsubscribe(); incomingCallUnsubscribe = null; }
    endCall();
    notificationRows = []; updateNotificationBadge([]);
    allChatsCache = [];
  }

  function signOut(){
    stopListeners();
    activeChatId = null; activeOtherUid = null; currentUser = null;
    appAuth.signOut();
  }

  $('switchAuth').addEventListener('click', function(){
    isSignup = !isSignup;
    $('signupFields').classList.toggle('hidden', !isSignup);
    $('forgotPasswordRow').classList.toggle('hidden', isSignup);
    $('authTitle').textContent = isSignup ? 'Create your account' : 'Welcome back';
    $('authSubtitle').textContent = isSignup ? 'Join dot.tag.' : 'Log in to continue.';
    $('authSubmit').textContent = isSignup ? 'Create account' : 'Log in';
    $('switchText').textContent = isSignup ? 'Already have an account?' : 'New to dot.tag?';
    $('switchAuth').textContent = isSignup ? 'Log in' : 'Create account';
    showStatus('authStatus','');
  });

  $('forgotPasswordBtn').addEventListener('click', function(){
    if(isSignup) return;
    if(!bootFirebase()) return;
    var existingEmail = $('email').value.trim().toLowerCase();
    dotDialog({
      type:'prompt', title:'Reset your password',
      message:'Enter the email address linked to your dot.tag account.',
      value:existingEmail, multiline:false, inputType:'email', maxLength:254, okText:'Send reset link'
    }).then(function(value){
      if(value === null) return;
      var email = String(value || '').trim().toLowerCase();
      if(!email){ return dotAlert('Please enter your email address.', 'Email required'); }
      if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){ return dotAlert('Enter a valid email address.', 'Check your email'); }
      var button = $('forgotPasswordBtn'); button.disabled = true; button.textContent = 'Sending…';
      return appAuth.sendPasswordResetEmail(email).then(function(){
        $('email').value = email;
        showStatus('authStatus','If an account exists, a reset link has been sent.');
        return dotAlert('Check your inbox and spam folder for the reset link.', 'Check your email');
      }).catch(function(error){
        var code = error && error.code ? error.code : '';
        var message = 'Could not send the reset email.';
        if(code === 'auth/invalid-email') message = 'That email is not valid.';
        else if(code === 'auth/too-many-requests') message = 'Too many attempts. Wait a while.';
        else if(code === 'auth/network-request-failed') message = 'Network error. Check your connection.';
        return dotAlert(message, 'Password reset');
      }).finally(function(){ button.disabled = false; button.textContent = 'Forgot password?'; });
    });
  });

  $('authSubmit').addEventListener('click', function(){
    if(!bootFirebase()) return;
    var email = $('email').value.trim().toLowerCase(), pass = $('password').value;
    if(!email || !pass){ showStatus('authStatus','Enter email and password.'); return; }
    if(pass.length < 6){ showStatus('authStatus','Password must be at least 6 characters.'); return; }
    var button = $('authSubmit'); button.disabled = true; showStatus('authStatus','Please wait…');

    if(isSignup){
      var name = $('displayName').value.trim(), username = $('username').value.trim().toLowerCase();
      if(!name || name.length > 40 || !/^[a-z0-9_]{3,20}$/.test(username)){
        button.disabled = false; showStatus('authStatus','Enter a display name and username (3–20 lowercase letters, numbers or _).'); return;
      }
      usernameReservePath(username).get().then(function(reserveDoc){
        if(reserveDoc.exists){
          button.disabled = false;
          showStatus('authStatus','That username is already taken.');
          return null;
        }
        return appAuth.createUserWithEmailAndPassword(email, pass).then(function(cred){
          return cred.user.updateProfile({displayName:name}).then(function(){
            return usernameReservePath(username).set({ uid: cred.user.uid, createdAt: firebase.firestore.FieldValue.serverTimestamp() })
              .then(function(){
                return profilePath(cred.user.uid).set({
                  displayName: name, username: username,
                  createdAt: firebase.firestore.FieldValue.serverTimestamp()
                });
              });
          });
        });
      }).then(function(){ showStatus('authStatus',''); })
        .catch(function(e){ showStatus('authStatus', e.message || 'Could not sign up.'); button.disabled = false; });
      return;
    }

    appAuth.signInWithEmailAndPassword(email, pass).then(function(){
      showStatus('authStatus','');
    }).catch(function(e){
      showStatus('authStatus', e.message || 'Could not sign in.'); button.disabled = false;
    });
  });

  function updateNotificationBadge(rows){
    var unread = (rows || []).filter(function(n){ return n.read !== true; }).length;
    var badge = $('notifyBadge');
    badge.textContent = unread > 99 ? '99+' : String(unread);
    badge.classList.toggle('hidden', unread === 0);
  }
  function notificationActorProfile(uid){ return getCachedProfile(uid); }
  function createNotification(data){
    if(!store || !data || !data.recipientId || !data.actorId || data.recipientId === data.actorId) return Promise.resolve();
    if(data.actorId !== currentUser.uid) return Promise.resolve();
    return notificationActorProfile(data.actorId).then(function(p){
      var payload = {
        recipientId: data.recipientId,
        actorId: currentUser.uid,
        actorName: p.displayName || p.username || (currentUser.displayName || 'dot.tag user'),
        actorPhoto: p.profileImage || '',
        type: data.type, read: false,
        createdAt: firebase.firestore.FieldValue.serverTimestamp()
      };
      if(data.chatId) payload.chatId = data.chatId;
      if(data.messageId) payload.messageId = data.messageId;
      return notificationPath().add(payload);
    });
  }

  function listenNotifications(){
    if(unsubscribeNotifications){ unsubscribeNotifications(); unsubscribeNotifications = null; }
    if(!store || !currentUser) return;
    unsubscribeNotifications = notificationPath().where('recipientId','==',currentUser.uid).limit(30).onSnapshot(function(snap){
      notificationRows = snap.docs.map(function(d){ var n = d.data(); n.id = d.id; return n; }).sort(function(a,b){
        var at = a.createdAt && a.createdAt.toMillis ? a.createdAt.toMillis() : 0;
        var bt = b.createdAt && b.createdAt.toMillis ? b.createdAt.toMillis() : 0;
        return bt - at;
      });
      updateNotificationBadge(notificationRows);
      if(!$('notificationsView').classList.contains('hidden')) renderNotifications(notificationRows);
      notificationPath().where('recipientId','==',currentUser.uid).where('read','==',false).get().then(function(s){
        var badge = $('notifyBadge');
        badge.textContent = s.size > 99 ? '99+' : String(s.size);
        badge.classList.toggle('hidden', s.size === 0);
      }).catch(function(){});
    }, function(e){ console.error('Notifications unavailable', e); });
  }

  function renderNotifications(rows){
    var box = $('notificationList'); box.innerHTML = '';
    if(!rows.length){ box.innerHTML = '<div class="empty"><div class="big">🔔</div><strong>No notifications yet</strong></div>'; return; }
    rows.forEach(function(n){
      var row = document.createElement('div');
      row.className = 'notification-row' + (n.read === true ? '' : ' unread');
      var name = n.actorName || 'dot.tag user';
      var avDiv = document.createElement('div'); avDiv.className = 'avatar';
      if (n.actorPhoto) {
        var img = document.createElement('img'); img.src = n.actorPhoto; img.alt = ''; avDiv.appendChild(img);
      } else {
        avDiv.textContent = initials(name);
      }
      var copyDiv = document.createElement('div'); copyDiv.className = 'notification-copy';
      var strong = document.createElement('strong'); strong.textContent = name; strong.style.fontWeight = '600';
      var textMsg = '';
      if (n.type === 'follow') textMsg = ' started following you';
      else if (n.type === 'message') textMsg = ' sent you a message';
      else if (n.type === 'follow_request') textMsg = ' requested to follow you';
      else if (n.type === 'follow_accepted') textMsg = ' accepted your follow request';
      else if (n.type === 'missed_call') textMsg = ' 📞 Missed call';
      else textMsg = ' interacted';
      var text = document.createTextNode(textMsg);
      var timeDiv = document.createElement('div'); timeDiv.className = 'notification-time'; timeDiv.textContent = notificationTime(n.createdAt);
      copyDiv.appendChild(strong); copyDiv.appendChild(text); copyDiv.appendChild(timeDiv);

      if (n.type === 'follow_request') {
        var actionDiv = document.createElement('div');
        actionDiv.style.cssText = 'display:flex;gap:8px;margin-top:8px;';

        var acceptBtn = document.createElement('button');
        acceptBtn.className = 'primary'; acceptBtn.textContent = 'Accept';
        acceptBtn.style.cssText = 'font-size:11px;padding:5px 14px;min-height:auto;border-radius:6px;';

        var rejectBtn = document.createElement('button');
        rejectBtn.className = 'secondary'; rejectBtn.textContent = 'Reject';
        rejectBtn.style.cssText = 'font-size:11px;padding:5px 14px;min-height:auto;border-radius:6px;border-color:var(--line);color:var(--muted);';

        acceptBtn.onclick = function(e) {
          e.stopPropagation();
          var followRef = followPath(n.actorId, currentUser.uid);
          followRef.update({ status: 'accepted' }).then(function(){
            createNotification({recipientId: n.actorId, actorId: currentUser.uid, type: 'follow_accepted'});
            actionDiv.innerHTML = '<span class="muted small">Accepted</span>';
            notificationPath().doc(n.id).delete();
          }).catch(function(err){ dotAlert('Error: ' + err.message); });
        };

        rejectBtn.onclick = function(e) {
          e.stopPropagation();
          var followRef = followPath(n.actorId, currentUser.uid);
          followRef.delete().then(function(){
            actionDiv.innerHTML = '<span class="muted small">Rejected</span>';
            notificationPath().doc(n.id).delete();
          }).catch(function(err){ dotAlert('Error: ' + err.message); });
        };

        actionDiv.appendChild(acceptBtn);
        actionDiv.appendChild(rejectBtn);
        copyDiv.appendChild(actionDiv);
      }

      row.appendChild(avDiv); row.appendChild(copyDiv);
      if (n.read !== true) {
        var dot = document.createElement('span'); dot.className = 'notification-dot'; row.appendChild(dot);
      }
      row.addEventListener('click', function(){
        var ref = notificationPath().doc(n.id);
        var mark = n.read === true ? Promise.resolve() : ref.update({read:true});
        mark.catch(function(){}).then(function(){
          n.read = true; row.classList.remove('unread');
          var dot = row.querySelector('.notification-dot'); if(dot) dot.remove();
          updateNotificationBadge(notificationRows);
          if(n.type === 'message' && n.chatId && n.actorId){ openChat(n.chatId, n.actorId, n.actorName || 'Conversation'); }
          else if(n.actorId){ openPublicProfile(n.actorId, 'notificationsView'); }
        });
      });
      attachLongPress(row, function(){ return [{label:'Delete notification', danger:true, run:function(){ deleteNotification(n); }}]; });
      box.appendChild(row);
    });
  }

  function markAllNotificationsRead(){
    if(!currentUser || !store) return;
    var unread = notificationRows.filter(function(n){ return n.read !== true; });
    if(!unread.length){ showStatus('notificationStatus','All caught up.'); return; }
    var batches = [];
    for(var i = 0; i < unread.length; i += 400){
      var b = store.batch();
      unread.slice(i, i + 400).forEach(function(n){ b.update(notificationPath().doc(n.id), {read:true}); });
      batches.push(b.commit());
    }
    Promise.all(batches).then(function(){ showStatus('notificationStatus','All marked as read.'); }).catch(function(e){ showStatus('notificationStatus','Failed: ' + e.message); });
  }
  function clearAllNotifications(){
    if(!currentUser || !store) return;
    if(!notificationRows.length){ showStatus('notificationStatus','No notifications.'); return; }
    dotConfirm('Clear all notifications?', 'Clear notifications', true).then(function(ok){
      if(!ok) return;
      var rows = notificationRows.slice(), jobs = [];
      for(var i = 0; i < rows.length; i += 400){
        var b = store.batch();
        rows.slice(i, i + 400).forEach(function(n){ if(n.id) b.delete(notificationPath().doc(n.id)); });
        jobs.push(b.commit());
      }
      Promise.all(jobs).then(function(){ showStatus('notificationStatus','Cleared.'); }).catch(function(e){ dotAlert('Failed: ' + e.message); });
    });
  }
  function deleteNotification(n){
    if(!currentUser || !n || !n.id) return;
    confirmDelete('notification').then(function(ok){
      if(!ok) return;
      notificationPath().doc(n.id).delete().catch(function(e){ dotAlert('Failed: ' + e.message); });
    });
  }

  function renderChatList(searchStr) {
    var list = $('chatList'); list.innerHTML = '';
    var search = (searchStr || '').toLowerCase();
    var filtered = allChatsCache.filter(function(c) {
      return !search || c.name.toLowerCase().indexOf(search) !== -1 || (c.username && c.username.toLowerCase().indexOf(search) !== -1);
    });
    if(!filtered.length){
      list.innerHTML = '<div class="empty"><div class="big">💬</div><strong>No chats found</strong><p>Try searching differently or tap + to find someone.</p></div>';
      return;
    }
    filtered.forEach(function(c){
      var row = document.createElement('div'); row.className = 'chat-row';
      var avatarHtml = c.profileImage ? '<img src="' + esc(c.profileImage) + '" />' : esc(initials(c.name));
      row.innerHTML = '<div class="avatar">' + avatarHtml + '</div><div class="grow"><div class="chat-name truncate">' + esc(c.name) + '</div><div class="chat-preview truncate">' + esc(c.lastMessage || 'Start a conversation') + '</div></div><span class="muted small">›</span>';
      row.addEventListener('click', function(){ openChat(c.id, c.other, c.name); });
      attachLongPress(row, function(){ return [{label:'Delete conversation', danger:true, run:function(){ deleteChatConversation(c.id); }}]; });
      list.appendChild(row);
    });
  }
  function listenChats(){
    if(unsubscribeChats) unsubscribeChats();
    if(!store || !currentUser) return;
    unsubscribeChats = store.collection('chats').where('participants','array-contains',currentUser.uid).onSnapshot(function(snapshot){
      var docs = snapshot.docs.slice().sort(function(a,b){
        var at = a.data().updatedAt && a.data().updatedAt.toMillis ? a.data().updatedAt.toMillis() : 0;
        var bt = b.data().updatedAt && b.data().updatedAt.toMillis ? b.data().updatedAt.toMillis() : 0;
        return bt - at;
      });
      var promises = docs.map(function(doc) {
        var d = doc.data(), other = (d.participants || []).filter(function(uid){ return uid !== currentUser.uid; })[0];
        if(!other) return Promise.resolve(null);
        var clearedAt = d['clearedAt_' + currentUser.uid] ? d['clearedAt_' + currentUser.uid].toMillis() : 0;
        var lastMsgTime = d.updatedAt ? d.updatedAt.toMillis() : 0;
        var displayLastMessage = d.lastMessage;
        if (clearedAt > 0 && lastMsgTime <= clearedAt) displayLastMessage = 'Start a conversation';
        return getCachedProfile(other).then(function(p){
          if(!p || !p.username) return null;
          return { id: doc.id, other: other, name: p.displayName || p.username || 'dot.tag user', username: p.username, profileImage: p.profileImage || '', lastMessage: displayLastMessage };
        });
      });
      Promise.all(promises).then(function(results) {
        allChatsCache = results.filter(function(r) { return r !== null; });
        renderChatList($('chatSearch').value);
      });
    }, function(err){ console.error(err); $('chatList').innerHTML = '<div class="empty">Could not load chats.</div>'; });
  }
  $('chatSearch').addEventListener('input', function(){ renderChatList(this.value); });

  function deleteChatConversation(chatId){
    if(!currentUser || !chatId) return;
    confirmDelete('conversation').then(function(ok){
      if(!ok) return;
      var ref = store.collection('chats').doc(chatId);
      function deleteMessagesBatch(){
        return ref.collection('messages').limit(400).get().then(function(snap){
          if(snap.empty) return null;
          var batch = store.batch();
          snap.docs.forEach(function(d){ batch.delete(d.ref); });
          return batch.commit().then(deleteMessagesBatch);
        });
      }
      deleteMessagesBatch().then(function(){
        return ref.delete();
      }).then(function(){
        if(activeChatId === chatId){ activeChatId = null; showView('chatsView'); }
      }).catch(function(e){ dotAlert('Failed: ' + e.message); });
    });
  }

  function deleteOwnMessage(chatId, messageId, senderId){
    if(!currentUser || senderId !== currentUser.uid){ dotAlert('You can delete only your own message.'); return; }
    confirmDelete('message').then(function(ok){
      if(!ok) return;
      store.collection('chats').doc(chatId).collection('messages').doc(messageId).delete().catch(function(e){ dotAlert('Failed: ' + e.message); });
    });
  }

  function startChat(){
    if(!currentUser) return;
    dotDialog({type:'prompt', title:'New conversation', message:'Enter their exact username (without @):', value:'', multiline:false, maxLength:20, okText:'Find user'}).then(function(username){
      if(!username) return;
      username = String(username).trim().toLowerCase();
      if(!/^[a-z0-9_]{3,20}$/.test(username)){ dotAlert('Username must be 3–20 lowercase letters, numbers or _.'); return; }
      store.collection('profiles').where('username','==',username).limit(2).get().then(function(snap){
        if(snap.empty){ dotAlert('Username not found.'); return; }
        if(snap.size > 1){ dotAlert('Username is duplicated.'); return; }
        var otherDoc = snap.docs[0], other = otherDoc.id, p = otherDoc.data();
        if(other === currentUser.uid){ dotAlert('You cannot chat with yourself.'); return; }
        var ids = [currentUser.uid, other].sort(), chatId = ids.join('_'), ref = store.collection('chats').doc(chatId);
        return ref.get().then(function(d){
          if(d.exists) return;
          return ref.set({ participants: ids, createdAt: firebase.firestore.FieldValue.serverTimestamp(), updatedAt: firebase.firestore.FieldValue.serverTimestamp(), lastMessage: '', lastSenderId: '' });
        }).then(function(){ openChat(chatId, other, p.displayName || p.username || 'Conversation'); });
      }).catch(function(e){ dotAlert('Could not start chat: ' + e.message); });
    });
  }
  $('newChatBtn').addEventListener('click', startChat);

  function markMessagesRead(chatId) {
    if(!currentUser || !store) return;
    store.collection('chats').doc(chatId).collection('messages')
      .orderBy('createdAt', 'desc').limit(50).get().then(function(snap){
        if(snap.empty) return;
        var batch = store.batch();
        var updatesMade = false;
        snap.docs.forEach(function(doc){
          var d = doc.data();
          if (d.senderId !== currentUser.uid) {
            if (!d.readBy || d.readBy[currentUser.uid] !== true) {
              var u = {};
              u['readBy.' + currentUser.uid] = true;
              batch.update(doc.ref, u);
              updatesMade = true;
            }
          }
        });
        if (updatesMade) return batch.commit();
      }).catch(function(e){ console.warn('Read receipt update failed:', e.message); });
  }

  function sendTypingState(chatId, isTyping) {
    if(!currentUser || !chatId) return;
    var ref = store.collection('chats').doc(chatId);
    var payload = {};
    payload['typing.' + currentUser.uid] = isTyping ? firebase.firestore.FieldValue.serverTimestamp() : null;
    ref.update(payload).catch(function(){});
  }

  function applyChatWallpaper(chatId) {
    var box = $('messages');
    var savedBg = null;
    try{ savedBg = localStorage.getItem('chat_bg_' + chatId); }catch(e){}
    if (savedBg) {
      box.style.backgroundImage = 'url(' + savedBg + ')';
      box.classList.add('custom-bg');
    } else {
      box.style.backgroundImage = 'none';
      box.classList.remove('custom-bg');
    }
  }

  function openChat(chatId, otherUid, name){
    if(unsubscribeMessages){ unsubscribeMessages(); unsubscribeMessages = null; }
    if(unsubscribeOlderMsgs){ unsubscribeOlderMsgs(); unsubscribeOlderMsgs = null; }
    if(typingUnsub){ typingUnsub(); typingUnsub = null; }
    if(unsubscribePresence){ unsubscribePresence(); unsubscribePresence = null; }

    activeChatId = chatId; activeOtherUid = otherUid;
    oldestMsgDoc = null; olderMsgLoading = false;
    $('roomName').textContent = name;
    $('roomAvatar').textContent = initials(name);
    $('messages').innerHTML = '';
    $('typingIndicator').innerHTML = '';
    $('loadOlderMessages').classList.add('hidden');
    showView('chatRoomView');
    applyChatWallpaper(chatId);

    getCachedProfile(otherUid).then(function(p) {
      if(p && p.profileImage) {
        $('roomAvatar').innerHTML = '<img src="' + esc(p.profileImage) + '" style="width:100%;height:100%;object-fit:cover;" />';
      }
    });
    $('roomAvatar').onclick = function() {
      if (activeOtherUid) openPublicProfile(activeOtherUid, 'chatRoomView');
    };

    unsubscribePresence = userPresencePath(otherUid).onSnapshot(function(doc){
      if(!doc.exists) return;
      var pr = doc.data();
      $('roomStatus').textContent = pr.online ? 'Online' : formatLastSeen(pr.lastSeen);
    }, function(){});

    markMessagesRead(chatId);

    var clearedTime = 0;
    store.collection('chats').doc(chatId).get().then(function(chatDoc){
      if(chatDoc.exists && chatDoc.data()['clearedAt_' + currentUser.uid]) {
        clearedTime = chatDoc.data()['clearedAt_' + currentUser.uid].toMillis();
      }
      unsubscribeMessages = store.collection('chats').doc(chatId).collection('messages')
        .orderBy('createdAt','desc').limit(30).onSnapshot(function(snap){
          var box = $('messages'); box.innerHTML = '';
          if(snap.empty){ box.innerHTML = '<div class="empty">Say hello 👋</div>'; return; }
          snap.docs.forEach(function(doc){
            var d = doc.data();
            var msgTime = d.createdAt ? d.createdAt.toMillis() : 0;
            if (clearedTime > 0 && msgTime <= clearedTime) return;
            var mine = d.senderId === currentUser.uid;
            var el = document.createElement('div');
            el.className = 'bubble' + (mine ? ' mine' : '');
            el.setAttribute('data-message-id', doc.id);
            if(d.imageUrl){
              var img = document.createElement('img');
              img.className = 'bubble-image'; img.src = d.imageUrl; img.alt = ''; img.loading = 'lazy';
              el.appendChild(img);
            }
            if(d.text){
              var textEl = document.createElement('div');
              textEl.className = 'bubble-text'; textEl.textContent = d.text;
              el.appendChild(textEl);
            }
            var timeEl = document.createElement('div');
            timeEl.className = 'bubble-time';
            var tick = '';
            if(mine){
              var otherRead = d.readBy && d.readBy[otherUid];
              tick = '<span class="read-tick ' + (otherRead ? 'read' : 'sent') + '">' + (otherRead ? '✓✓' : '✓') + '</span>';
            }
            timeEl.innerHTML = (tick ? tick + ' ' : '') + esc(formatMessageTime(d.createdAt));
            el.appendChild(timeEl);
            if(mine) attachLongPress(el, function(){ return [{label:'Delete message', danger:true, run:function(){ deleteOwnMessage(chatId, doc.id, d.senderId); }}]; });
            box.appendChild(el);
          });
          markMessagesRead(chatId);
          if(snap.docs.length >= 30){
            oldestMsgDoc = snap.docs[snap.docs.length - 1];
            $('loadOlderMessages').classList.remove('hidden');
          }
        }, function(e){ $('messages').innerHTML = '<div class="empty">Messages unavailable.</div>'; });
    });

    typingUnsub = store.collection('chats').doc(chatId).onSnapshot(function(doc){
      if(!doc.exists) return;
      var d = doc.data();
      var t = d.typing && d.typing[otherUid];
      var ms = t ? (t.toMillis ? t.toMillis() : t) : 0;
      var typing = ms && (Date.now() - ms < 5000);
      $('typingIndicator').innerHTML = typing ? '<span class="dot"></span><span class="dot"></span><span class="dot"></span> typing…' : '';
    }, function(){});

    var msgInput = $('messageInput');
    if (msgInput) {
      msgInput.addEventListener('focus', function() {
        setTimeout(function() {
          var box = $('messages');
          if (box) box.scrollTop = 0;
        }, 300);
      });
    }
  }

  $('backToChats').addEventListener('click', function(){
    showView('chatsView');
    if(unsubscribeMessages){ unsubscribeMessages(); unsubscribeMessages = null; }
    if(unsubscribeOlderMsgs){ unsubscribeOlderMsgs(); unsubscribeOlderMsgs = null; }
    if(typingUnsub){ typingUnsub(); typingUnsub = null; }
    if(unsubscribePresence){ unsubscribePresence(); unsubscribePresence = null; }
    if(activeChatId) sendTypingState(activeChatId, false);
  });

  $('loadOlderMessages').addEventListener('click', function(){
    if(!activeChatId || olderMsgLoading || !oldestMsgDoc) return;
    olderMsgLoading = true;
    var btn = this; btn.disabled = true; btn.textContent = 'Loading…';
    store.collection('chats').doc(activeChatId).collection('messages')
      .orderBy('createdAt','desc').startAfter(oldestMsgDoc).limit(30).get().then(function(snap){
        if(snap.empty){ btn.classList.add('hidden'); return; }
        oldestMsgDoc = snap.docs[snap.docs.length - 1];
        var box = $('messages');
        snap.docs.forEach(function(doc){
          var d = doc.data();
          var mine = d.senderId === currentUser.uid;
          var el = document.createElement('div');
          el.className = 'bubble' + (mine ? ' mine' : '');
          if(d.imageUrl){
            var img = document.createElement('img');
            img.className = 'bubble-image'; img.src = d.imageUrl; img.alt = ''; img.loading = 'lazy';
            el.appendChild(img);
          }
          if(d.text){
            var textEl = document.createElement('div');
            textEl.className = 'bubble-text'; textEl.textContent = d.text;
            el.appendChild(textEl);
          }
          var timeEl = document.createElement('div');
          timeEl.className = 'bubble-time';
          var tick = '';
          if(mine){
            var otherRead = d.readBy && d.readBy[activeOtherUid];
            tick = '<span class="read-tick ' + (otherRead ? 'read' : 'sent') + '">' + (otherRead ? '✓✓' : '✓') + '</span>';
          }
          timeEl.innerHTML = (tick ? tick + ' ' : '') + esc(formatMessageTime(d.createdAt));
          el.appendChild(timeEl);
          box.appendChild(el);
        });
        btn.textContent = 'Load older messages';
      }).catch(function(e){ btn.textContent = 'Failed'; console.warn(e); })
      .then(function(){ olderMsgLoading = false; btn.disabled = false; });
  });

  $('messageForm').addEventListener('submit', function(e){
    e.preventDefault();
    if(!currentUser || !activeChatId) return;
    var input = $('messageInput'), text = input.value.trim();
    if(!text) return;
    if(text.length > 2000){ dotAlert('Messages must be 2,000 characters or fewer.'); return; }
    input.value = '';
    var chat = store.collection('chats').doc(activeChatId), msg = chat.collection('messages').doc();
    var batch = store.batch();
    var msgData = { senderId: currentUser.uid, text: text, createdAt: firebase.firestore.FieldValue.serverTimestamp(), readBy: {} };
    msgData.readBy[currentUser.uid] = true;
    batch.set(msg, msgData);
    batch.update(chat, { lastMessage: text, lastSenderId: currentUser.uid, updatedAt: firebase.firestore.FieldValue.serverTimestamp() });
    batch.commit().then(function(){
      return createNotification({recipientId: activeOtherUid, actorId: currentUser.uid, type:'message', chatId: activeChatId, messageId: msg.id});
    }).catch(function(e){ console.error(e); });
    sendTypingState(activeChatId, false);
  });

