  (function(){
    var card = $('profile3dCard'); if(!card) return;
    var active=false;
    function tilt(e){
      var r=card.getBoundingClientRect(); if(!r.width||!r.height) return;
      var x=((e.clientX-r.left)/r.width-.5), y=((e.clientY-r.top)/r.height-.5);
      card.style.transform='perspective(900px) rotateX('+(-y*4).toFixed(2)+'deg) rotateY('+(x*5).toFixed(2)+'deg)';
      card.style.boxShadow='0 22px 44px rgba(20,70,150,.18),inset 0 1px 0 rgba(255,255,255,.12)';
    }
    function reset(){ active=false; card.style.transform='perspective(900px) rotateX(0deg) rotateY(0deg)'; card.style.boxShadow=''; }
    card.addEventListener('pointermove',function(e){ if(e.pointerType==='mouse'||active) tilt(e); });
    card.addEventListener('pointerdown',function(e){ active=true; if(e.pointerType!=='mouse') tilt(e); });
    card.addEventListener('pointerup',reset); card.addEventListener('pointercancel',reset); card.addEventListener('pointerleave',reset);
  })();

