  $('saveProfile').addEventListener('click', function(){
    if(!currentUser){ showStatus('profileStatus','Please log in.'); return; }
    var name = $('editDisplayName').value.trim(), bio = $('editBio').value.trim();
    var isPrivate = $('editIsPrivate').checked;
    if(!name || name.length > 40){ showStatus('profileStatus','Display name is required (max 40).'); return; }
    if(bio.length > 160){ showStatus('profileStatus','Bio must be 160 characters or fewer.'); return; }
    var btn = $('saveProfile'); btn.disabled = true; showStatus('profileStatus','Saving…');
    var upd = { displayName: name, bio: bio, isPrivate: isPrivate, updatedAt: firebase.firestore.FieldValue.serverTimestamp() };
    if(pendingProfileImageUrl !== null) upd.profileImage = pendingProfileImageUrl;
    profilePath(currentUser.uid).set(upd, { merge: true }).then(function(){
      invalidateProfileCache(currentUser.uid);
      return getCachedProfile(currentUser.uid);
    }).then(function(p){
      setProfile(currentUser, p);
      pendingProfileImageUrl = null;
