      showStatus('profileStatus','Save failed: ' + (e.message || ''));
    }).then(function(){ btn.disabled = false; });
  });

  var searchDebounce = null;
  $('peopleSearch').addEventListener('input', function(e) {
    var query = e.target.value.trim().toLowerCase();
    var box = $('peopleResults');
    if (!query) { box.innerHTML = '<div class="empty"><div class="big">&#8981;</div>Search for a dot.tag user to start connecting.</div>'; return; }
    clearTimeout(searchDebounce);
    searchDebounce = setTimeout(function() {
      var collected = [];
      function page(lastDoc) {
        var q = store.collection('profiles').orderBy('username').limit(100);
        if (lastDoc) q = q.startAfter(lastDoc);
        return q.get().then(function(snap) {
          snap.forEach(function(doc) {
            var data = doc.data();
            var nm = (data.displayName || '').toLowerCase();
            var un = (data.username || '').toLowerCase();
            if ((nm.indexOf(query) !== -1 || un.indexOf(query) !== -1) && doc.id !== currentUser.uid) collected.push({ id: doc.id, data: data });
          });
          if (snap.size === 100 && collected.length < 20) return page(snap.docs[snap.docs.length - 1]);
        });
      }
      page(null).then(function() {
        box.innerHTML = '';
        if (!collected.length) { box.innerHTML = '<div class="empty">No users found for "' + esc(query) + '".</div>'; return; }
        collected.slice(0, 20).forEach(function(res) {
          var p = res.data;
          var displayName = p.displayName || p.username || 'dot.tag user';
          var resultCard = document.createElement('div');
          resultCard.className = 'people-result';
          resultCard.style.cssText = 'margin-bottom:14px;border-bottom:1px solid var(--line-soft);padding-bottom:14px;';
          var avatarHtml = p.profileImage ? '<img src="' + esc(p.profileImage) + '" />' : esc(initials(displayName));
          resultCard.innerHTML = '<div class="people-result-main"><div class="avatar">' + avatarHtml + '</div><div class="grow"><strong class="people-result-name" style="font-size:14px">' + esc(displayName) + '</strong><div class="muted small">@' + esc(p.username) + '</div></div></div><div class="people-result-actions"><button class="secondary view-btn" type="button" style="border-radius:6px">View Profile</button><button class="primary follow-btn" data-follow-button type="button" style="border-radius:6px">Follow</button></div>';
          resultCard.querySelector('.view-btn').onclick = function() { openPublicProfile(res.id, 'exploreView'); };
          renderFollowButton(res.id, resultCard);
          box.appendChild(resultCard);
        });
      }).catch(function(err) { box.textContent = 'Error: ' + err.message; });
    }, 500);
  });

  function loadSuggestions() {
    if(!currentUser || !store) return;
    var container = $('suggestedUsersList');
    if(!container) return;
    container.innerHTML = '<span class="muted small">Loading suggestions...</span>';
    store.collection('profiles').limit(15).get().then(function(snap) {
      container.innerHTML = '';
      var promises = [];
      snap.forEach(function(doc) {
        if (doc.id === currentUser.uid) return;
        var pData = doc.data();
        if (pData.isPrivate === true) return;
        promises.push(followPath(currentUser.uid, doc.id).get().then(function(followDoc) {
          if (!followDoc.exists) return { id: doc.id, data: pData };
          return null;
        }));
      });
      Promise.all(promises).then(function(results) {
        var validUsers = results.filter(function(u) { return u !== null; });
        if (validUsers.length === 0) { container.innerHTML = '<span class="muted small">No new suggestions right now.</span>'; return; }
        validUsers.sort(function() { return 0.5 - Math.random(); });
        validUsers.slice(0, 8).forEach(function(user) {
          var p = user.data;
          var name = p.displayName || p.username || 'dot.tag user';
          var avatarHtml = p.profileImage ? '<img src="' + esc(p.profileImage) + '" style="width:100%;height:100%;object-fit:cover;" />' : esc(initials(name));
          var card = document.createElement('div');
          card.style.cssText = 'min-width:110px;max-width:110px;display:flex;flex-direction:column;align-items:center;text-align:center;padding:10px;background:var(--panel);border:1px solid var(--line);border-radius:10px;';
          card.innerHTML = '<div class="avatar" style="width:54px;height:54px;margin-bottom:8px;font-size:20px;">' + avatarHtml + '</div><strong class="truncate" style="font-size:12px;width:100%;margin-bottom:2px;">' + esc(name) + '</strong><div class="muted small truncate" style="font-size:10px;width:100%;margin-bottom:10px;">@' + esc(p.username || 'user') + '</div><button class="primary follow-btn" data-follow-button type="button" style="width:100%;font-size:11px;padding:6px;min-height:30px;border-radius:6px;">Follow</button>';
          card.querySelector('.avatar').style.cursor = 'pointer';
          card.querySelector('.avatar').onclick = function() { openPublicProfile(user.id, 'exploreView'); };
          card.querySelector('strong').style.cursor = 'pointer';
          card.querySelector('strong').onclick = function() { openPublicProfile(user.id, 'exploreView'); };
          renderFollowButton(user.id, card);
          container.appendChild(card);
        });
      });
    }).catch(function(e) { container.innerHTML = '<span class="muted small">Could not load suggestions.</span>'; console.error(e); });
  }
  var refreshBtn = $('refreshSuggestions');
  if(refreshBtn) refreshBtn.addEventListener('click', loadSuggestions);

  $('publicProfileBack').addEventListener('click', function(){
    if (publicProfileBackView === 'chatRoomView' && activeChatId) {
      openChat(activeChatId, activeOtherUid, $('roomName').textContent);
    } else {
      showView(publicProfileBackView || 'exploreView');
    }
  });
  $('openFollowers').addEventListener('click', function(){ loadFollowList('followers', currentUser && currentUser.uid, false); });
  $('openFollowing').addEventListener('click', function(){ loadFollowList('following', currentUser && currentUser.uid, false); });
  $('closeFollowList').addEventListener('click', function(){ $('followListCard').classList.add('hidden'); });
  $('openPublicFollowers').addEventListener('click', function(){ loadFollowList('followers', publicProfileUid, true); });
  $('openPublicFollowing').addEventListener('click', function(){ loadFollowList('following', publicProfileUid, true); });
  $('closePublicFollowList').addEventListener('click', function(){ $('publicFollowListCard').classList.add('hidden'); });

  $('deleteAccountBtn').addEventListener('click', function(){
    if(!currentUser) return;
    dotDialog({type:'prompt', title:'Delete account', message:'Type DELETE to confirm. All your data will be permanently removed.', value:'', multiline:false, maxLength:20, okText:'Delete account', danger:true}).then(function(input){
      if(input !== 'DELETE'){ if(input !== null) dotAlert('Cancelled — text did not match.'); return; }
      var uid = currentUser.uid;
      showStatus('profileStatus', 'Deleting data... Please wait.');

      function deleteQueryPaged(query) {
        return query.limit(400).get().then(function(snap){
          if(snap.empty) return null;
          var batch = store.batch();
          snap.docs.forEach(function(d){ batch.delete(d.ref); });
          return batch.commit().then(function(){ return deleteQueryPaged(query); });
        });
      }
      function deleteSubcollection(parentRef, name) {
        return deleteQueryPaged(parentRef.collection(name));
      }
      function deleteMyChats() {
        return store.collection('chats').where('participants','array-contains',uid).limit(40).get().then(function(snap){
          if(snap.empty) return null;
          return snap.docs.reduce(function(chain, chatDoc){
            return chain.then(function(){
              return deleteSubcollection(chatDoc.ref, 'messages').then(function(){ return chatDoc.ref.delete(); });
            });
          }, Promise.resolve()).then(deleteMyChats);
        });
      }
      function deleteMyPosts() {
        return store.collection('posts').where('authorId','==',uid).limit(40).get().then(function(snap){
          if(snap.empty) return null;
          return snap.docs.reduce(function(chain, postDoc){
            return chain.then(function(){
              return deleteSubcollection(postDoc.ref, 'likes').then(function(){ return postDoc.ref.delete(); });
            });
          }, Promise.resolve()).then(deleteMyPosts);
        });
      }
      function deleteUsernames() {
        return deleteQueryPaged(store.collection('usernames').where('uid','==',uid));
      }

      Promise.all([
        deleteMyPosts(),
        deleteQueryPaged(store.collection('follows').where('followerId','==',uid)),
        deleteQueryPaged(store.collection('follows').where('followingId','==',uid)),
        deleteQueryPaged(store.collection('notifications').where('recipientId','==',uid)),
        deleteQueryPaged(store.collection('notifications').where('actorId','==',uid)),
        deleteMyChats(),
        profilePath(uid).delete().catch(function(){}),
        userPresencePath(uid).delete().catch(function(){}),
        deleteUsernames()
      ]).then(function(){
        return currentUser.delete();
      }).then(function(){
        dotAlert('Account deleted.');
      }).catch(function(e){
        dotAlert('Could not fully delete account (recent login may be required): ' + e.message);
      });
    });
  });

  var touchStart = 0, touchMove = 0, isRefreshing = false;
  var ptrIndicator = $('ptrIndicator');
  var ptrThreshold = 80;
  function ptrEligible() { return !$('homeView').classList.contains('hidden') || !$('exploreView').classList.contains('hidden'); }
  document.addEventListener('touchstart', function(e) {
    if (!ptrEligible()) return;
    if (window.scrollY === 0) touchStart = e.touches[0].clientY;
  }, { passive: true });
  document.addEventListener('touchmove', function(e) {
    if (!ptrEligible()) return;
    if (touchStart > 0 && window.scrollY === 0 && !isRefreshing) {
      touchMove = e.touches[0].clientY;
      var distance = touchMove - touchStart;
      if (distance > 0) {
        if (e.cancelable) e.preventDefault();
        var pullDistance = Math.min(distance * 0.5, 100);
        if (pullDistance > 20) {
          ptrIndicator.classList.add('visible');
          ptrIndicator.style.transform = 'translateX(-50%) translateY(' + (pullDistance - 20) + 'px)';
          ptrIndicator.classList.toggle('refreshing', pullDistance > ptrThreshold);
        }
      }
    }
  }, { passive: false });
  document.addEventListener('touchend', function() {
    if (!ptrEligible()) { touchStart = 0; touchMove = 0; return; }
    if (touchStart > 0 && !isRefreshing) {
      var distance = touchMove - touchStart;
      var pullDistance = Math.min(distance * 0.5, 100);
      if (pullDistance > ptrThreshold) {
        isRefreshing = true;
        ptrIndicator.classList.add('refreshing');
        ptrIndicator.style.transform = 'translateX(-50%) translateY(' + (ptrThreshold - 20) + 'px)';
        setTimeout(function() {
          if (currentUser) {
            invalidateProfileCache(currentUser.uid);
            getCachedProfile(currentUser.uid).then(function(p){ setProfile(currentUser, p); });
            if (!$('homeView').classList.contains('hidden')) listenPosts();
            if (!$('exploreView').classList.contains('hidden')) loadSuggestions();
          }
          ptrIndicator.classList.remove('visible', 'refreshing');
          ptrIndicator.style.transform = 'translateX(-50%) translateY(-70px)';
          isRefreshing = false;
        }, 800);
      } else {
        ptrIndicator.classList.remove('visible', 'refreshing');
        ptrIndicator.style.transform = 'translateX(-50%) translateY(-70px)';
      }
      touchStart = 0; touchMove = 0;
    }
  }, { passive: true });

  /* ============================================================
     WEBRTC CALLS — fully preserved
     ============================================================ */
  var servers = {
    iceServers: [
      { urls: ['stun:stun1.l.google.com:19302', 'stun:stun2.l.google.com:19302'] }
    ],
    iceCandidatePoolSize: 10,
    bundlePolicy: 'max-bundle'
  };
  if (window.DOT_TAG_TURN_CONFIG && Array.isArray(window.DOT_TAG_TURN_CONFIG.iceServers)) {
    servers.iceServers = servers.iceServers.concat(window.DOT_TAG_TURN_CONFIG.iceServers);
  }

  function startCallTimer() {
    stopCallTimer();
    callStartTime = Date.now();
    var el = $('callTimer');
    if (el) el.classList.remove('hidden');
    callTimerInterval = setInterval(function() {
      var sec = Math.floor((Date.now() - callStartTime) / 1000);
      var m = Math.floor(sec / 60);
      var s = sec % 60;
      if (el) el.textContent = (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
    }, 500);
  }
  function stopCallTimer() {
    if (callTimerInterval) { clearInterval(callTimerInterval); callTimerInterval = null; }
    var el = $('callTimer');
    if (el) { el.classList.add('hidden'); el.textContent = '00:00'; }
    callStartTime = null;
  }

  function resetCallButtons() {
    micMuted = false; camOff = false;
    $('muteBtn').classList.remove('off');
    $('camBtn').classList.remove('off');
    $('speakerBtn').classList.remove('on');
    $('acceptCallBtn').classList.add('hidden');
    $('callStatus').textContent = '';
  }
  function showCallModal(statusText) {
    resetCallButtons();
    $('callStatus').textContent = statusText || '';
    $('callModal').classList.add('active');
  }

  function createMissedCallNotification(receiverId, callerId, callerName) {
    if (!store || !receiverId || !callerId) return;
    getCachedProfile(callerId).then(function(p) {
      return notificationPath().add({
        recipientId: receiverId,
        actorId: callerId,
        actorName: p.displayName || p.username || callerName || 'dot.tag user',
        actorPhoto: p.profileImage || '',
        type: 'missed_call',
        read: false,
        createdAt: firebase.firestore.FieldValue.serverTimestamp()
      });
    }).catch(function(){});
  }

  $('startCallBtn').addEventListener('click', async function() {
    if (!currentUser || !activeChatId || !activeOtherUid) return;
    if (peerConnection) { dotAlert('Already in a call.'); return; }

    callRole = 'caller';
    showCallModal('Ringing…');
    $('callStatus').textContent = 'Ringing…';

    if (callTimeoutTimer) clearTimeout(callTimeoutTimer);
    callTimeoutTimer = setTimeout(function() {
      if (callDocRef && !peerConnection) {
        callDocRef.update({ status: 'missed' }).catch(function(){});
      }
    }, 30000);

    try {
      currentCallId = store.collection('calls').doc().id;
      callDocRef = callPath(currentCallId);

      await callDocRef.set({
        callerId: currentUser.uid,
        receiverId: activeOtherUid,
        status: 'ringing',
        offer: null,
        answer: null,
        createdAt: firebase.firestore.FieldValue.serverTimestamp()
      });

      await setupPeerConnection(true);

      if (callUnsubscribe) callUnsubscribe();
      callUnsubscribe = callDocRef.onSnapshot(async function(snap) {
        if (!snap.exists) return endCall();
        var data = snap.data();

        if (data.status === 'accepted') {
          if (callTimeoutTimer) { clearTimeout(callTimeoutTimer); callTimeoutTimer = null; }
          $('callStatus').textContent = 'Connecting…';
          if (data.answer && peerConnection && !peerConnection.currentRemoteDescription) {
            try {
              await peerConnection.setRemoteDescription(new RTCSessionDescription(data.answer));
              $('callStatus').textContent = 'Connected';
              if (!callTimerInterval) startCallTimer();
            } catch(e){ console.warn('remote desc err', e); }
          }
        }
        if (data.status === 'rejected') { dotAlert('Call declined'); endCall(); }
        if (data.status === 'missed') { dotAlert('No answer — call missed'); endCall(); }
        if (data.status === 'ended') endCall();
      });

      if (remoteCandidateUnsub) remoteCandidateUnsub();
      remoteCandidateUnsub = callDocRef.collection('receiverCandidates').onSnapshot(function(snapshot) {
        snapshot.docChanges().forEach(function(change) {
          if (change.type === 'added' && peerConnection) {
            peerConnection.addIceCandidate(new RTCIceCandidate(change.doc.data())).catch(function(e){ console.warn('ICE candidate rejected:', e); });
          }
        });
      });

    } catch (err) {
      console.error('Start call error:', err);
      if (err.code === 'permission-denied') {
        dotAlert('Firestore Permission Denied. Please make sure you published the latest rules in Firebase Console.');
      } else {
        dotAlert('Could not start call: ' + err.message);
      }
      endCall();
    }
  });

  function listenForIncomingCalls() {
    if (!currentUser) return;
    if (incomingCallUnsubscribe) incomingCallUnsubscribe();
    incomingCallUnsubscribe = store.collection('calls')
      .where('receiverId', '==', currentUser.uid)
      .where('status', '==', 'ringing')
      .onSnapshot(function(snapshot) {
        snapshot.docChanges().forEach(async function(change) {
          if (change.type !== 'added') return;
          var data = change.doc.data();
          if (data.callerId === currentUser.uid) return;
          currentCallId = change.doc.id;
          callDocRef = change.doc.ref;
          callRole = 'receiver';
          showCallModal('Incoming call…');
          $('acceptCallBtn').classList.remove('hidden');

          if (callTimeoutTimer) clearTimeout(callTimeoutTimer);
          callTimeoutTimer = setTimeout(function() {
            if (callDocRef && !peerConnection) {
              callDocRef.update({ status: 'missed' }).catch(function(){});
              createMissedCallNotification(data.callerId, data.receiverId);
              endCall();
            }
          }, 30000);

          if (callUnsubscribe) callUnsubscribe();
          callUnsubscribe = callDocRef.onSnapshot(function(snap) {
            if (!snap.exists) return endCall();
            var d = snap.data();
            if (d.status === 'ended' || d.status === 'missed' || d.status === 'rejected') endCall();
          });

          $('acceptCallBtn').onclick = async function() {
            $('acceptCallBtn').classList.add('hidden');
            $('callStatus').textContent = 'Connecting…';
            if (callTimeoutTimer) { clearTimeout(callTimeoutTimer); callTimeoutTimer = null; }
            try {
              var freshSnap = await callDocRef.get();
              if (!freshSnap.exists) throw new Error('Call ended by caller.');

              var freshData = freshSnap.data();
              if (!freshData.offer) throw new Error('Call offer not ready. Please wait a second and try again.');

              await callDocRef.update({ status: 'accepted' });
              await setupPeerConnection(false, freshData.offer);
            } catch(e) {
              dotAlert('Could not accept call: ' + e.message);
              endCall();
            }
          };
        });
      }, function(e){ console.warn('incoming call listener err', e); });
  }

  async function setupPeerConnection(isCaller, offerObj) {
    try {
      if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) throw new Error('Camera and microphone require a secure HTTPS page and browser support.');
      localStream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'user' },
        audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true }
      });
      $('localVideo').srcObject = localStream;

      peerConnection = new RTCPeerConnection(servers);
      var remoteStream = new MediaStream();
      $('remoteVideo').srcObject = remoteStream;

      localStream.getTracks().forEach(function(track) { peerConnection.addTrack(track, localStream); });

      peerConnection.ontrack = function(event) {
        event.streams[0].getTracks().forEach(function(track) { remoteStream.addTrack(track); });
        $('callStatus').textContent = 'Connected';
        if (!callTimerInterval) startCallTimer();
      };

      peerConnection.onconnectionstatechange = function() {
        if (peerConnection.connectionState === 'failed') {
          dotAlert('Connection failed. Check your network or configure a TURN relay.');
          endCall();
        } else if (peerConnection.connectionState === 'disconnected') {
          $('callStatus').textContent = 'Reconnecting…';
          if (callTimeoutTimer) clearTimeout(callTimeoutTimer);
          callTimeoutTimer = setTimeout(function(){
            if (peerConnection && peerConnection.connectionState === 'disconnected') {
              dotAlert('Connection lost');
              endCall();
            }
          }, 12000);
        } else if (peerConnection.connectionState === 'connected') {
          if (callTimeoutTimer) { clearTimeout(callTimeoutTimer); callTimeoutTimer = null; }
          $('callStatus').textContent = 'Connected';
        }
      };

      peerConnection.onicecandidate = function(event) {
        if (!event.candidate || !callDocRef) return;
        var colName = isCaller ? 'callerCandidates' : 'receiverCandidates';
        callDocRef.collection(colName).add(event.candidate.toJSON()).catch(function(){});
      };

      if (isCaller) {
        var offer = await peerConnection.createOffer();
        await peerConnection.setLocalDescription(offer);
        await callDocRef.update({ offer: { type: offer.type, sdp: offer.sdp } });
      } else {
        if (!offerObj) throw new Error('Call offer is missing.');
        await peerConnection.setRemoteDescription(new RTCSessionDescription(offerObj));
        var answer = await peerConnection.createAnswer();
        await peerConnection.setLocalDescription(answer);
        await callDocRef.update({ answer: { type: answer.type, sdp: answer.sdp } });
        if (callerCandidateUnsub) callerCandidateUnsub();
        callerCandidateUnsub = callDocRef.collection('callerCandidates').onSnapshot(function(snapshot) {
          snapshot.docChanges().forEach(function(change) {
            if (change.type === 'added' && peerConnection) {
              peerConnection.addIceCandidate(new RTCIceCandidate(change.doc.data())).catch(function(e){ console.warn('ICE candidate rejected:', e); });
            }
          });
        });
      }
    } catch (err) {
      console.error('WebRTC setup error:', err);
      if (err.name === 'NotAllowedError') dotAlert('Camera/microphone permission denied. Please allow access.');
      else if (err.name === 'NotFoundError') dotAlert('No camera or microphone found on this device.');
      else dotAlert('Could not start call: ' + err.message);
      endCall();
    }
  }

  $('muteBtn').addEventListener('click', function() {
    if (!localStream) return;
    micMuted = !micMuted;
    localStream.getAudioTracks().forEach(function(t){ t.enabled = !micMuted; });
    this.classList.toggle('off', micMuted);
  });

  $('camBtn').addEventListener('click', function() {
    if (!localStream) return;
    camOff = !camOff;
    localStream.getVideoTracks().forEach(function(t){ t.enabled = !camOff; });
    this.classList.toggle('off', camOff);
  });

  $('speakerBtn').addEventListener('click', function() {
    var remote = $('remoteVideo');
    if (!remote) return;
    var on = this.classList.toggle('on');
    try {
      if (remote.setSinkId && on) remote.setSinkId('default').catch(function(){});
      remote.volume = on ? 1 : 0.6;
    } catch(e){}
  });

  $('endCallBtn').addEventListener('click', function() {
    if (callRole === 'receiver' && callDocRef && peerConnection) {
      callDocRef.update({ status: 'rejected' }).catch(function(){});
    } else if (callRole === 'receiver' && callDocRef && !peerConnection) {
      callDocRef.update({ status: 'missed' }).catch(function(){});
    }
    endCall();
  });

  function endCall() {
    if (callTimeoutTimer) { clearTimeout(callTimeoutTimer); callTimeoutTimer = null; }
    stopCallTimer();
    if (peerConnection) { try { peerConnection.close(); } catch(e){} peerConnection = null; }
    if (localStream) { localStream.getTracks().forEach(function(t){ t.stop(); }); localStream = null; }
    if (callUnsubscribe) { callUnsubscribe(); callUnsubscribe = null; }
    if (remoteCandidateUnsub) { remoteCandidateUnsub(); remoteCandidateUnsub = null; }
    if (callerCandidateUnsub) { callerCandidateUnsub(); callerCandidateUnsub = null; }
    if (callDocRef) {
      callDocRef.update({ status: 'ended' }).catch(function(){});
      var _ref = callDocRef;
      setTimeout(function(){
        try { _ref.collection('callerCandidates').get().then(function(s){ s.forEach(function(d){ d.ref.delete(); }); }); } catch(e){}
        try { _ref.collection('receiverCandidates').get().then(function(s){ s.forEach(function(d){ d.ref.delete(); }); }); } catch(e){}
      }, 60000);
      callDocRef = null;
    }
    currentCallId = null;
    callRole = null;
    $('callModal').classList.remove('active');
    $('localVideo').srcObject = null;
    $('remoteVideo').srcObject = null;
    resetCallButtons();
  }


  /* ============================================================
     MITRA — partner discovery integrated into dot.tag
     Collections: partner_posts, partner_requests, partner_chats,
     user_blocks/{uid}/blocked, user_reports.
     ============================================================ */
  var mitraState = {posts:[], incoming:[], outgoing:[], activeChat:null, unsubPosts:null, unsubMessages:null};
  function mitraBlocked(uid){
    if(!currentUser || !uid) return Promise.resolve(false);
    return Promise.all([
      store.collection('user_blocks').doc(currentUser.uid).collection('blocked').doc(uid).get(),
      store.collection('user_blocks').doc(uid).collection('blocked').doc(currentUser.uid).get()
    ]).then(function(ds){ return ds.some(function(d){return d.exists;}); });
  }
  function mitraEnsureUI(){
    var root=$('exploreView'); if(!root || $('mitraLaunch')) return;
    var launch=document.createElement('div'); launch.className='mitra-launch'; launch.id='mitraLaunch';
    launch.innerHTML='<div class="eyebrow">Meet people with shared interests</div><h2 style="margin:5px 0">Mitra · Partner discovery</h2><p class="muted small">Find study, gaming, language-learning or project partners. Chat opens only after a request is accepted.</p><button class="primary" id="mitraOpenBtn" type="button">Open Mitra</button><div class="mitra-panel hidden" id="mitraPanel"><div class="mitra-actions"><button id="mitraBrowseBtn" type="button">Discover</button><button id="mitraRequestsBtn" type="button">Requests</button><button id="mitraNewBtn" type="button">Create post</button></div><div id="mitraComposer" class="mitra-form hidden"><label for="mitraCategory">Category</label><select id="mitraCategory" class="field"><option value="study">Study partner</option><option value="gaming">Gaming partner</option><option value="language">Language learning</option><option value="project">Project partner</option></select><label for="mitraTitle">Title</label><input id="mitraTitle" class="field" maxlength="80" placeholder="What kind of partner are you looking for?"/><label for="mitraBody">Details</label><textarea id="mitraBody" class="field" rows="3" maxlength="600" placeholder="Share your interests, availability and goals"></textarea><div class="mitra-actions"><button class="primary" id="mitraPublishBtn" type="button">Publish</button><button id="mitraCancelBtn" type="button">Cancel</button></div></div><div id="mitraStatus" class="mitra-status" aria-live="polite"></div><div id="mitraContent"></div></div>';
    var content=root.querySelector('.content'); if(content) content.appendChild(launch);
    $('mitraOpenBtn').addEventListener('click',function(){ $('mitraPanel').classList.toggle('hidden'); mitraLoadPosts(); });
    $('mitraBrowseBtn').addEventListener('click',mitraLoadPosts);
    $('mitraRequestsBtn').addEventListener('click',mitraLoadRequests);
    $('mitraNewBtn').addEventListener('click',function(){ $('mitraComposer').classList.remove('hidden'); });
    $('mitraCancelBtn').addEventListener('click',function(){ $('mitraComposer').classList.add('hidden'); });
    $('mitraPublishBtn').addEventListener('click',mitraPublishPost);
  }
  function mitraStatus(t){ if($('mitraStatus')) $('mitraStatus').textContent=t||''; }
  function mitraRenderPosts(docs){
    var box=$('mitraContent'); if(!box)return; box.innerHTML='';
    if(!docs.length){box.innerHTML='<div class="empty">No open partner posts yet. Create the first one.</div>';return;}
    docs.forEach(function(doc){var d=doc.data(), el=document.createElement('article'); el.className='mitra-post';
      el.innerHTML='<div class="eyebrow">'+esc(String(d.category||'community').toUpperCase())+'</div><h3>'+esc(d.title||'Partner request')+'</h3><p>'+esc(d.body||'')+'</p><div class="muted small">By '+esc(d.displayName||'dot.tag member')+' · @'+esc(d.username||'member')+'</div><div class="mitra-actions" data-actions="1"></div>';
      var actions=el.querySelector('[data-actions]');
      if(d.ownerId===currentUser.uid){var edit=document.createElement('button');edit.textContent='Edit';edit.onclick=function(){mitraEditPost(doc.id,d);};actions.appendChild(edit);var del=document.createElement('button');del.textContent='Delete';del.onclick=function(){mitraDeletePost(doc.id);};actions.appendChild(del);}
      else {var connect=document.createElement('button');connect.className='primary';connect.textContent='Request to connect';connect.onclick=function(){mitraSendRequest(doc.id,d.ownerId);};actions.appendChild(connect);var report=document.createElement('button');report.textContent='Report';report.onclick=function(){mitraReport('partner_post',doc.id,d.ownerId);};var block=document.createElement('button');block.textContent='Block';block.onclick=function(){dotConfirm('Block this member? Their discovery posts will be hidden from you.','Block member',true).then(function(ok){if(ok)mitraBlockUser(d.ownerId);});};actions.appendChild(block);actions.appendChild(report);}
      box.appendChild(el);
    });
  }
  function mitraLoadPosts(){
    if(!currentUser || !store)return; mitraStatus('Loading partner posts…');
    store.collection('partner_posts').where('status','==','open').orderBy('createdAt','desc').limit(50).get().then(function(snap){
      var docs=snap.docs.slice();
      return Promise.all(docs.map(function(doc){return mitraBlocked(doc.data().ownerId).then(function(blocked){return blocked?null:doc;});}));
    }).then(function(docs){mitraStatus('');mitraRenderPosts(docs.filter(Boolean));}).catch(function(e){mitraStatus('Could not load posts: '+e.message);});
  }
  function mitraPublishPost(){
    if(!currentUser)return; var title=$('mitraTitle').value.trim(), body=$('mitraBody').value.trim(), category=$('mitraCategory').value;
    if(title.length<4 || body.length<10){mitraStatus('Add a title and at least 10 characters of details.');return;}
    mitraStatus('Publishing…');
    profilePath(currentUser.uid).get().then(function(p){var d=p.data()||{};return store.collection('partner_posts').add({ownerId:currentUser.uid,displayName:d.displayName||'dot.tag member',username:d.username||'',category:category,title:title,body:body,status:'open',createdAt:firebase.firestore.FieldValue.serverTimestamp(),updatedAt:firebase.firestore.FieldValue.serverTimestamp()});})
    .then(function(){ $('mitraTitle').value='';$('mitraBody').value='';$('mitraComposer').classList.add('hidden');mitraStatus('Your partner post is live.');mitraLoadPosts();})
    .catch(function(e){mitraStatus('Publish failed: '+e.message);});
  }
  function mitraEditPost(id,d){
    dotDialog({type:'prompt',title:'Edit partner post',message:'Update the post details:',value:d.body||'',multiline:true,maxLength:600,okText:'Save'}).then(function(body){if(body===null)return;body=String(body).trim();if(body.length<10){dotAlert('Please enter at least 10 characters.');return;}store.collection('partner_posts').doc(id).update({body:body,updatedAt:firebase.firestore.FieldValue.serverTimestamp()}).then(mitraLoadPosts).catch(function(e){dotAlert('Update failed: '+e.message);});});
  }
  function mitraDeletePost(id){dotConfirm('Delete this partner post?','Delete post',true).then(function(ok){if(!ok)return;store.collection('partner_posts').doc(id).delete().then(mitraLoadPosts).catch(function(e){dotAlert('Delete failed: '+e.message);});});}
  function mitraSendRequest(postId,receiverId){
    if(!currentUser||receiverId===currentUser.uid)return; mitraBlocked(receiverId).then(function(blocked){if(blocked)throw new Error('This account is unavailable.');return store.collection('partner_requests').add({senderId:currentUser.uid,receiverId:receiverId,postId:postId,status:'pending',createdAt:firebase.firestore.FieldValue.serverTimestamp(),updatedAt:firebase.firestore.FieldValue.serverTimestamp()});})
    .then(function(){mitraStatus('Connection request sent.');}).catch(function(e){mitraStatus(e.message||'Could not send request.');});
  }
  function mitraLoadRequests(){
    if(!currentUser)return; var box=$('mitraContent');box.innerHTML='';mitraStatus('Loading requests…');
    Promise.all([store.collection('partner_requests').where('receiverId','==',currentUser.uid).where('status','==','pending').limit(50).get(),store.collection('partner_requests').where('senderId','==',currentUser.uid).where('status','==','pending').limit(50).get()])
    .then(function(snaps){mitraStatus('');var incoming=snaps[0].docs,outgoing=snaps[1].docs;if(!incoming.length&&!outgoing.length){box.innerHTML='<div class="empty">No pending connection requests.</div>'; }
      incoming.forEach(function(doc){var d=doc.data(),el=document.createElement('div');el.className='mitra-post';el.innerHTML='<strong>Incoming request</strong><div class="muted small">From '+esc(d.senderId)+'</div><div class="mitra-actions"><button class="primary" data-accept>Accept</button><button data-decline>Decline</button></div>';el.querySelector('[data-accept]').onclick=function(){mitraResolveRequest(doc.id,d,true);};el.querySelector('[data-decline]').onclick=function(){mitraResolveRequest(doc.id,d,false);};box.appendChild(el);});
      outgoing.forEach(function(doc){var d=doc.data(),el=document.createElement('div');el.className='mitra-post';el.textContent='Request sent to '+d.receiverId;box.appendChild(el);});
      store.collection('partner_chats').where('participants','array-contains',currentUser.uid).limit(50).get().then(function(chats){if(chats.empty)return;var heading=document.createElement('h3');heading.textContent='Your accepted connections';box.appendChild(heading);chats.forEach(function(c){var row=document.createElement('div');row.className='mitra-post';row.innerHTML='<div class="mitra-actions"><button class="primary" type="button">Open connected chat</button></div>';row.querySelector('button').onclick=function(){mitraOpenPartnerChat(c.id);};box.appendChild(row);});}).catch(function(e){mitraStatus('Could not load accepted chats: '+e.message);});
    }).catch(function(e){mitraStatus('Could not load requests: '+e.message);});
  }
  function mitraResolveRequest(id,d,accept){
    var ref=store.collection('partner_requests').doc(id), chatId=[d.senderId,d.receiverId].sort().join('_');
    var job=ref.update({status:accept?'accepted':'declined',updatedAt:firebase.firestore.FieldValue.serverTimestamp()});
    if(accept) job=job.then(function(){var chatRef=store.collection('partner_chats').doc(chatId);return chatRef.get().then(function(existing){if(existing.exists)return;return chatRef.set({participants:[d.senderId,d.receiverId].sort(),requestId:id,createdAt:firebase.firestore.FieldValue.serverTimestamp(),updatedAt:firebase.firestore.FieldValue.serverTimestamp()});});});
    job.then(function(){mitraLoadRequests();mitraStatus(accept?'Connection accepted. Open the chat below.':'Request declined.');if(accept)mitraOpenPartnerChat(chatId);}).catch(function(e){mitraStatus('Action failed: '+e.message);});
  }
  function mitraOpenPartnerChat(chatId){
    var box=$('mitraContent');box.innerHTML='<h3>Connected chat</h3><div id="mitraMessages" class="mitra-post"></div><form id="mitraMessageForm" class="mitra-actions"><input id="mitraMessageText" class="field" maxlength="1000" placeholder="Write a message…" style="flex:1;min-width:0"/><button class="primary" type="submit">Send</button></form>';
    var msgRef=store.collection('partner_chats').doc(chatId).collection('messages');
    if(mitraState.unsubMessages)mitraState.unsubMessages();
    mitraState.unsubMessages=msgRef.orderBy('createdAt','asc').limit(100).onSnapshot(function(s){var m=$('mitraMessages');if(!m)return;m.innerHTML='';s.forEach(function(doc){var d=doc.data(),p=document.createElement('p');p.textContent=(d.senderId===currentUser.uid?'You: ':'Partner: ')+(d.text||'');m.appendChild(p);});});
    $('mitraMessageForm').addEventListener('submit',function(ev){ev.preventDefault();var input=$('mitraMessageText'),text=input.value.trim();if(!text)return;input.value='';msgRef.add({senderId:currentUser.uid,text:text,createdAt:firebase.firestore.FieldValue.serverTimestamp()}).then(function(){return store.collection('partner_chats').doc(chatId).update({updatedAt:firebase.firestore.FieldValue.serverTimestamp()});}).catch(function(e){mitraStatus('Message failed: '+e.message);});});
  }
  function mitraReport(type,targetId,reportedUid){
    dotDialog({type:'prompt',title:'Report content or account',message:'Briefly tell us why this should be reviewed:',value:'',multiline:true,maxLength:300,okText:'Submit report'}).then(function(reason){if(!reason||!String(reason).trim())return;store.collection('user_reports').add({reporterId:currentUser.uid,reportedUid:reportedUid||null,targetType:type,targetId:targetId,reason:String(reason).trim(),status:'open',createdAt:firebase.firestore.FieldValue.serverTimestamp()}).then(function(){mitraStatus('Report submitted for review.');}).catch(function(e){mitraStatus('Report failed: '+e.message);});});
  }
  function mitraBlockUser(uid){if(!uid||uid===currentUser.uid)return;store.collection('user_blocks').doc(currentUser.uid).collection('blocked').doc(uid).set({blockedUid:uid,createdAt:firebase.firestore.FieldValue.serverTimestamp()}).then(function(){mitraStatus('Account blocked.');mitraLoadPosts();}).catch(function(e){mitraStatus('Could not block: '+e.message);});}
  mitraEnsureUI();

  /* ============================================================
     BOOT
     ============================================================ */
  initTheme();
  if(bootFirebase()){
    appAuth.onAuthStateChanged(function(user){
      if(user){ startApp(user); }
      else { stopListeners(); currentUser = null; storage = null; showView('authView'); }
    }, function(){ showView('authView'); });
  } else { showView('authView'); }
})();
//
